(397, '3.2.268', 42, 'Lokale Parameterkonfundierung', 'Lineare oder nahezu lineare Abhängigkeit zweier Parametersensitivitäten.', 's_i=cs_j', 's_i=cs_j', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(398, '3.2.269', 42, 'Beobachtungsoperator eines dynamischen Systems', 'Abbildung von Anfangszustand und Parametern auf eine vollständige Beobachtungstrajektorie.', '\\mathcal{O}:(x_0,\\theta)\\longmapsto y(\\cdot)', '\\mathcal{O}:(x_0,\\theta)\\longmapsto y(\\cdot)', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45);
INSERT INTO `definitions` (`definition_id`, `definition_number`, `section_id`, `title`, `definition_text`, `formal_latex`, `word_latex`, `provenance`, `source_id`, `assumptions`, `notes`, `validation_status`, `created_revision_id`) VALUES
(399, '3.2.270', 42, 'Dynamische Identifizierbarkeit', 'Eindeutige Bestimmbarkeit von Anfangszustand und Parametern aus der Beobachtungstrajektorie.', '\\mathcal{O}(x_{0,1},\\theta_1)=\\mathcal{O}(x_{0,2},\\theta_2)\\Longrightarrow(x_{0,1},\\theta_1)=(x_{0,2},\\theta_2)', '\\mathcal{O}(x_{0,1},\\theta_1)=\\mathcal{O}(x_{0,2},\\theta_2)\\Longrightarrow(x_{0,1},\\theta_1)=(x_{0,2},\\theta_2)', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(400, '3.2.271', 42, 'A-priori-Verteilung', 'Wahrscheinlichkeitsverteilung des unbekannten Zustands vor Einbeziehung aktueller Beobachtungen.', '\\pi_{\\mathrm{prior}}(u)', '\\pi_{\\mathrm{prior}}(u)', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(401, '3.2.272', 42, 'Likelihood-Funktion', 'Wahrscheinlichkeit der Beobachtung unter Voraussetzung eines Zustands.', '\\pi(y\\mid u)', '\\pi(y\\mid u)', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(402, '3.2.273', 42, 'A-posteriori-Verteilung', 'Nach Bayes aktualisierte Wahrscheinlichkeitsverteilung des Zustands.', '\\pi(u\\mid y)\\propto\\pi(y\\mid u)\\pi_{\\mathrm{prior}}(u)', '\\pi(u\\mid y)\\propto\\pi(y\\mid u)\\pi_{\\mathrm{prior}}(u)', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(403, '3.2.274', 42, 'MAP-Schätzer', 'Zustand mit maximaler A-posteriori-Dichte.', 'u_{\\mathrm{MAP}}=\\operatorname*{arg\\,max}_{u}\\pi(u\\mid y)', 'u_{\\mathrm{MAP}}=\\operatorname*{arg\\,max}_{u}\\pi(u\\mid y)', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(404, '3.2.275', 42, 'Rekonstruktionsunsicherheit', 'Menge oder Verteilung der mit Daten und Modellannahmen vereinbaren Zustände.', '\\mathcal{C}_{1-\\alpha}\\subset X', '\\mathcal{C}_{1-\\alpha}\\subset X', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(405, '3.2.276', 42, 'Auflösungsmatrix', 'Abbildung des wahren auf den regularisiert rekonstruierten Zustand.', 'M_\\alpha=R_\\alpha A', 'M_\\alpha=R_\\alpha A', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(406, '3.2.277', 42, 'Datengetragener Zustandsanteil', 'Zustandsanteil, dessen Bestimmung überwiegend durch Beobachtungsdaten getragen wird.', '\\sigma_i\\gg0', '\\sigma_i\\gg0', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(407, '3.2.278', 42, 'Regularisierungsgetragener Zustandsanteil', 'Zustandsanteil, dessen Bestimmung wesentlich durch Regularisierung oder Vorwissen geprägt wird.', '\\sigma_i\\approx0', '\\sigma_i\\approx0', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(408, '3.2.279', 42, 'FRZK-Vorwärtsabbildung', 'Abbildung von FRZK-Zustand und Parametern auf eine modellierte Beobachtung.', '\\mathcal{F}_{\\mathrm{FRZK}}:\\mathcal{U}\\times\\Theta\\rightarrow\\mathcal{Y}', '\\mathcal{F}_{\\mathrm{FRZK}}:\\mathcal{U}\\times\\Theta\\rightarrow\\mathcal{Y}', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(409, '3.2.280', 42, 'FRZK-Zustandsrekonstruktion', 'Minimierer eines regularisierten FRZK-Datenanpassungsfunktionals.', 'J_\\alpha(u)=D(\\mathcal{F}_{\\mathrm{FRZK}}(u,\\theta),y^\\delta)+\\alpha R(u)', 'J_\\alpha(u)=D(\\mathcal{F}_{\\mathrm{FRZK}}(u,\\theta),y^\\delta)+\\alpha R(u)', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(410, '3.2.281', 42, 'Gemeinsame Zustands- und Parameterrekonstruktion', 'Gekoppelte gleichzeitige Rekonstruktion von Zustand und Modellparametern.', '(u^\\ast,\\theta^\\ast)=\\operatorname*{arg\\,min}_{u,\\theta}J(u,\\theta)', '(u^\\ast,\\theta^\\ast)=\\operatorname*{arg\\,min}_{u,\\theta}J(u,\\theta)', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(411, '3.2.282', 42, 'Kopplungsregularisierte Rekonstruktion', 'Rekonstruktion mit Daten-, Glättungs- und Kopplungsanteil.', 'u_{\\alpha,\\beta}^{\\delta}=\\operatorname*{arg\\,min}_{u}\\left[D(\\mathcal{F}(u),y^\\delta)+\\alpha R_{\\mathrm{Glätte}}(u)+\\beta R_{\\mathrm{Kopplung}}(u)\\right]', 'u_{\\alpha,\\beta}^{\\delta}=\\operatorname*{arg\\,min}_{u}\\left[D(\\mathcal{F}(u),y^\\delta)+\\alpha R_{\\mathrm{Glätte}}(u)+\\beta R_{\\mathrm{Kopplung}}(u)\\right]', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(412, '3.2.283', 42, 'Zeitlich regularisierte Zustandsrekonstruktion', 'Rekonstruktion mit Datenanpassung und zeitlichem Regularisierungsanteil.', 'u_\\alpha^\\delta=\\operatorname*{arg\\,min}_{u}\\left[J_{\\mathrm{Daten}}(u)+\\alpha J_{\\mathrm{Zeit}}(u)\\right]', 'u_\\alpha^\\delta=\\operatorname*{arg\\,min}_{u}\\left[J_{\\mathrm{Daten}}(u)+\\alpha J_{\\mathrm{Zeit}}(u)\\right]', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(413, '3.2.284', 42, 'Gesamtvariation', 'Integral der Norm des Gradienten als sprungerhaltende Regularisierungsgröße.', '\\operatorname{TV}(u)=\\int_{\\Omega}\\|\\nabla u(x)\\|\\,\\mathrm{d}x', '\\operatorname{TV}(u)=\\int_{\\Omega}\\|\\nabla u(x)\\|\\,\\mathrm{d}x', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(414, '3.2.285', 42, 'Sparsitätsregularisierte Rekonstruktion', 'Rekonstruktion mit l1-Regularisierung der Darstellungskoeffizienten.', 'c_\\alpha^\\delta=\\operatorname*{arg\\,min}_{c}\\left[\\|\\mathcal{F}(\\Psi c)-y^\\delta\\|^2+\\alpha\\|c\\|_1\\right]', 'c_\\alpha^\\delta=\\operatorname*{arg\\,min}_{c}\\left[\\|\\mathcal{F}(\\Psi c)-y^\\delta\\|^2+\\alpha\\|c\\|_1\\right]', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(415, '3.2.286', 42, 'Gesamtbeobachtungsabweichung', 'Summe aus Mess-, Modell- und Diskretisierungsfehler.', 'e_{\\mathrm{gesamt}}=e_{\\mathrm{Messung}}+e_{\\mathrm{Modell}}+e_{\\mathrm{Diskretisierung}}', 'e_{\\mathrm{gesamt}}=e_{\\mathrm{Messung}}+e_{\\mathrm{Modell}}+e_{\\mathrm{Diskretisierung}}', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(416, '3.2.287', 42, 'Rekonstruktionsresiduum', 'Differenz zwischen aus der Rekonstruktion modellierter und beobachteter Größe.', 'r_\\alpha^\\delta=\\mathcal{F}(u_\\alpha^\\delta)-y^\\delta', 'r_\\alpha^\\delta=\\mathcal{F}(u_\\alpha^\\delta)-y^\\delta', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(417, '3.2.288', 42, 'Externe Rekonstruktionsvalidierung', 'Validierung anhand von Daten, die nicht zur Rekonstruktion verwendet wurden.', 'E_{\\mathrm{val}}=\\|\\mathcal{F}_{\\mathrm{val}}(u_\\alpha^\\delta)-y_{\\mathrm{val}}\\|', 'E_{\\mathrm{val}}=\\|\\mathcal{F}_{\\mathrm{val}}(u_\\alpha^\\delta)-y_{\\mathrm{val}}\\|', 'adapted', 88, 'Voraussetzungen gemäß Abschnitt 3.2.26.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 45),
(422, '3.2.289', 43, 'Wahrscheinlichkeitsraum', 'Tripel aus Ergebnismenge, Sigma-Algebra und Wahrscheinlichkeitsmaß.', '(\\Omega,\\mathcal{A},\\mathbb{P})', '(\\Omega,\\mathcal{A},\\mathbb{P})', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(423, '3.2.290', 43, 'Ereignis', 'Messbare Teilmenge des Ergebnisraums.', 'A\\in\\mathcal{A}', 'A\\in\\mathcal{A}', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(424, '3.2.291', 43, 'Reelle Zufallsvariable', 'Messbare Abbildung vom Ergebnisraum in die reellen Zahlen.', 'X:\\Omega\\rightarrow\\mathbb{R}', 'X:\\Omega\\rightarrow\\mathbb{R}', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(425, '3.2.292', 43, 'Zufallsvektor', 'Messbare Abbildung vom Ergebnisraum in einen endlichdimensionalen reellen Vektorraum.', 'X:\\Omega\\rightarrow\\mathbb{R}^{n}', 'X:\\Omega\\rightarrow\\mathbb{R}^{n}', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(426, '3.2.293', 43, 'Verteilungsfunktion', 'Wahrscheinlichkeit, dass eine Zufallsvariable einen gegebenen Wert nicht überschreitet.', 'F_X(x)=\\mathbb{P}(X\\leq x)', 'F_X(x)=\\mathbb{P}(X\\leq x)', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(427, '3.2.294', 43, 'Wahrscheinlichkeitsdichte', 'Nichtnegative Dichtefunktion einer absolut stetigen Verteilung.', 'F_X(x)=\\int_{-\\infty}^{x}p_X(\\xi)\\,\\mathrm{d}\\xi', 'F_X(x)=\\int_{-\\infty}^{x}p_X(\\xi)\\,\\mathrm{d}\\xi', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(428, '3.2.295', 43, 'Erwartungswert', 'Wahrscheinlichkeitsgewichteter Mittelwert einer integrierbaren Zufallsvariable.', '\\mathbb{E}[X]=\\int_{\\Omega}X(\\omega)\\,\\mathrm{d}\\mathbb{P}(\\omega)', '\\mathbb{E}[X]=\\int_{\\Omega}X(\\omega)\\,\\mathrm{d}\\mathbb{P}(\\omega)', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(429, '3.2.296', 43, 'Varianz', 'Mittlere quadratische Abweichung einer Zufallsvariable von ihrem Erwartungswert.', '\\operatorname{Var}(X)=\\mathbb{E}[(X-\\mathbb{E}[X])^2]', '\\operatorname{Var}(X)=\\mathbb{E}[(X-\\mathbb{E}[X])^2]', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(430, '3.2.297', 43, 'Standardabweichung', 'Positive Quadratwurzel der Varianz.', '\\sigma_X=\\sqrt{\\operatorname{Var}(X)}', '\\sigma_X=\\sqrt{\\operatorname{Var}(X)}', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(431, '3.2.298', 43, 'Kovarianz', 'Gemeinsame mittlere Abweichung zweier Zufallsvariablen von ihren Erwartungswerten.', '\\operatorname{Cov}(X,Y)=\\mathbb{E}[(X-\\mathbb{E}[X])(Y-\\mathbb{E}[Y])]', '\\operatorname{Cov}(X,Y)=\\mathbb{E}[(X-\\mathbb{E}[X])(Y-\\mathbb{E}[Y])]', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(432, '3.2.299', 43, 'Korrelationskoeffizient', 'Normierte Kovarianz zweier Zufallsvariablen.', '\\rho_{X,Y}=\\frac{\\operatorname{Cov}(X,Y)}{\\sigma_X\\sigma_Y}', '\\rho_{X,Y}=\\frac{\\operatorname{Cov}(X,Y)}{\\sigma_X\\sigma_Y}', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(433, '3.2.300', 43, 'Kovarianzmatrix', 'Matrix aller paarweisen Kovarianzen eines Zufallsvektors.', 'C_X=\\mathbb{E}[(X-\\mathbb{E}[X])(X-\\mathbb{E}[X])^{\\mathsf{T}}]', 'C_X=\\mathbb{E}[(X-\\mathbb{E}[X])(X-\\mathbb{E}[X])^{\\mathsf{T}}]', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(434, '3.2.301', 43, 'Bedingte Wahrscheinlichkeit', 'Wahrscheinlichkeit eines Ereignisses unter der Voraussetzung eines anderen Ereignisses.', '\\mathbb{P}(A\\mid B)=\\frac{\\mathbb{P}(A\\cap B)}{\\mathbb{P}(B)}', '\\mathbb{P}(A\\mid B)=\\frac{\\mathbb{P}(A\\cap B)}{\\mathbb{P}(B)}', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(435, '3.2.302', 43, 'Bedingter Erwartungswert', 'Erwartungswert einer Zufallsvariable relativ zu einer Unter-Sigma-Algebra.', '\\mathbb{E}[X\\mid\\mathcal{G}]', '\\mathbb{E}[X\\mid\\mathcal{G}]', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(436, '3.2.303', 43, 'Stochastischer Prozess', 'Familie von Zufallsvariablen auf einem gemeinsamen Wahrscheinlichkeitsraum.', '\\{X_t\\}_{t\\in T}', '\\{X_t\\}_{t\\in T}', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(437, '3.2.304', 43, 'Realisierung eines stochastischen Prozesses', 'Für ein festes Ergebnis entstehender Pfad des Prozesses.', 't\\longmapsto X_t(\\omega)', 't\\longmapsto X_t(\\omega)', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(438, '3.2.305', 43, 'Mittelwertfunktion', 'Zeitabhängiger Erwartungswert eines stochastischen Prozesses.', 'm_X(t)=\\mathbb{E}[X_t]', 'm_X(t)=\\mathbb{E}[X_t]', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(439, '3.2.306', 43, 'Kovarianzfunktion', 'Kovarianz eines stochastischen Prozesses zwischen zwei Zeitpunkten.', 'C_X(s,t)=\\operatorname{Cov}(X_s,X_t)', 'C_X(s,t)=\\operatorname{Cov}(X_s,X_t)', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(440, '3.2.307', 43, 'Autokorrelationsfunktion', 'Erwartungswert des Produkts zweier Prozesswerte.', 'R_X(s,t)=\\mathbb{E}[X_sX_t]', 'R_X(s,t)=\\mathbb{E}[X_sX_t]', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(441, '3.2.308', 43, 'Strenge Stationarität', 'Invarianz aller endlichdimensionalen Verteilungen gegenüber Zeitverschiebungen.', '(X_{t_1},\\ldots,X_{t_n})\\overset{d}{=}(X_{t_1+h},\\ldots,X_{t_n+h})', '(X_{t_1},\\ldots,X_{t_n})\\overset{d}{=}(X_{t_1+h},\\ldots,X_{t_n+h})', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(442, '3.2.309', 43, 'Schwache Stationarität', 'Konstanter Mittelwert und nur von der Zeitdifferenz abhängige Kovarianz.', 'm_X(t)=\\mu,\\quad C_X(s,t)=C_X(t-s)', 'm_X(t)=\\mu,\\quad C_X(s,t)=C_X(t-s)', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(443, '3.2.310', 43, 'Inkrement eines Prozesses', 'Differenz zweier Prozesswerte zu verschiedenen Zeitpunkten.', '\\Delta X_{s,t}=X_t-X_s', '\\Delta X_{s,t}=X_t-X_s', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(444, '3.2.311', 43, 'Stationäre Inkremente', 'Inkremente, deren Verteilung nur von der Zeitdifferenz abhängt.', 'X_{t+h}-X_t\\ \\text{hängt in Verteilung nur von }h\\text{ ab}', 'X_{t+h}-X_t\\ \\text{hängt in Verteilung nur von }h\\text{ ab}', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(445, '3.2.312', 43, 'Unabhängige Inkremente', 'Unabhängigkeit von Prozesszuwächsen auf disjunkten Zeitintervallen.', 'X_{t_1}-X_{t_0},\\ldots,X_{t_n}-X_{t_{n-1}}\\ \\text{unabhängig}', 'X_{t_1}-X_{t_0},\\ldots,X_{t_n}-X_{t_{n-1}}\\ \\text{unabhängig}', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(446, '3.2.313', 43, 'Markov-Prozess', 'Prozess, dessen zukünftige bedingte Verteilung bei bekanntem Gegenwartszustand nicht von der vollständigen Vergangenheit abhängt.', '\\mathbb{P}(X_t\\in A\\mid\\mathcal{F}_s)=\\mathbb{P}(X_t\\in A\\mid X_s)', '\\mathbb{P}(X_t\\in A\\mid\\mathcal{F}_s)=\\mathbb{P}(X_t\\in A\\mid X_s)', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(447, '3.2.314', 43, 'Filtration', 'Wachsende Familie von Sigma-Algebren zur Darstellung verfügbarer Information.', '\\mathcal{F}_s\\subseteq\\mathcal{F}_t\\quad\\text{für }s\\leq t', '\\mathcal{F}_s\\subseteq\\mathcal{F}_t\\quad\\text{für }s\\leq t', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(448, '3.2.315', 43, 'Adaptierter Prozess', 'Prozess, dessen Wert zu jedem Zeitpunkt bezüglich der bis dahin verfügbaren Information messbar ist.', 'X_t\\ \\text{ist }\\mathcal{F}_t\\text{-messbar}', 'X_t\\ \\text{ist }\\mathcal{F}_t\\text{-messbar}', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(449, '3.2.316', 43, 'Martingal', 'Adaptierter integrierbarer Prozess mit unverändertem bedingtem Erwartungswert.', '\\mathbb{E}[M_t\\mid\\mathcal{F}_s]=M_s', '\\mathbb{E}[M_t\\mid\\mathcal{F}_s]=M_s', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
(450, '3.2.317', 43, 'Standard-Wiener-Prozess', 'Stetiger Prozess mit Startwert null sowie unabhängigen normalverteilten stationären Inkrementen.', 'W_t-W_s\\sim\\mathcal{N}(0,t-s)', 'W_t-W_s\\sim\\mathcal{N}(0,t-s)', 'adapted', 89, 'Voraussetzungen gemäß Abschnitt 3.2.27.', 'Etablierte Definition oder FRZK-Anschlussdefinition.', 'verified', 46),
