(4309, '3.4093', 74, 'Zulässiger Zustandsbereich', '\\mathcal{S}_{\\mathrm{zul}}\\subseteq\\mathcal{S}_{\\mathrm{el}}', '\\mathcal{S}_{\\mathrm{zul}}\\subseteq\\mathcal{S}_{\\mathrm{el}}\\qquad\\text{(3.4093)}', 'S_zul ist eine modellabhängig ausgewählte zulässige Teilmenge des Zustandsbereichs.', 'definition', 'original', NULL, 'Definition eines zulässigen Zustandsbereichs.', 'Modellfestlegung.', 'verified', 113),
(4310, '3.4094', 74, 'Zustandsbereichskohärenz', '\\forall k\\in\\{0,\\ldots,n\\}:\\delta_k\\in\\mathcal{S}_{\\mathrm{zul}}', '\\forall k\\in\\{0,\\ldots,n\\}:\\delta_k\\in\\mathcal{S}_{\\mathrm{zul}}\\qquad\\text{(3.4094)}', 'Alle Zustände einer Entwicklung verbleiben im zulässigen Zustandsbereich.', 'other', 'original', NULL, 'Definition der Zustandsbereichskohärenz.', 'S_zul ist ausgewiesen.', 'verified', 113),
(4311, '3.4095', 74, 'Abgeschlossenheit einer Transformation auf dem zulässigen Zustandsbereich', 'T\\left(\\mathcal{S}_{\\mathrm{zul}}\\right)\\subseteq\\mathcal{S}_{\\mathrm{zul}}', 'T\\left(\\mathcal{S}_{\\mathrm{zul}}\\right)\\subseteq\\mathcal{S}_{\\mathrm{zul}}\\qquad\\text{(3.4095)}', 'T bildet den zulässigen Zustandsbereich in sich selbst ab.', 'other', 'literature', 59, 'Standardmäßige Abgeschlossenheitsbedingung einer Abbildung auf einer Teilmenge.', 'T ist eine funktionale Transformation.', 'verified', 113),
(4312, '3.4096', 74, 'Potenzielle Invariante', 'I:\\mathcal{S}_{\\mathrm{el}}\\rightarrow\\mathcal{Y}', 'I:\\mathcal{S}_{\\mathrm{el}}\\rightarrow\\mathcal{Y}\\qquad\\text{(3.4096)}', 'I ordnet funktionalen Zuständen Werte in Y zu.', 'definition', 'original', NULL, 'Allgemeine Form einer potenziellen Invariante.', 'Y ist ein geeigneter Wertebereich.', 'verified', 113),
(4313, '3.4097', 74, 'Invarianzbedingung', 'I\\left(T(\\delta)\\right)=I(\\delta)\\qquad\\text{für alle }\\delta\\in\\mathcal{S}_{\\mathrm{el}}', 'I\\left(T(\\delta)\\right)=I(\\delta)\\qquad\\text{für alle }\\delta\\in\\mathcal{S}_{\\mathrm{el}}\\qquad\\text{(3.4097)}', 'I bleibt unter der Transformation T erhalten.', 'other', 'literature', 63, 'Standardform einer Invarianzbedingung.', 'I und T sind definiert.', 'verified', 113),
(4314, '3.4098', 74, 'Invariantenkohärenz einer Entwicklung', 'I(\\delta_0)=I(\\delta_1)=\\cdots=I(\\delta_n)', 'I(\\delta_0)=I(\\delta_1)=\\cdots=I(\\delta_n)\\qquad\\text{(3.4098)}', 'Die ausgewählte Größe I bleibt entlang der Entwicklung erhalten.', 'other', 'original', NULL, 'Folge aus schrittweiser Invarianz.', 'Endliche Entwicklung.', 'verified', 113),
(4315, '3.4099', 74, 'Toleranzbasierte lokale Kohärenz', '\\left\\|Q(\\delta_k)-Q(\\delta_{k-1})\\right\\|\\leq\\varepsilon', '\\left\\|Q(\\delta_k)-Q(\\delta_{k-1})\\right\\|\\leq\\varepsilon\\qquad\\text{(3.4099)}', 'Die Änderung einer ausgewählten Zustandsbeschreibung bleibt unter einer Toleranz.', 'other', 'literature', 63, 'Normbasierte Toleranzbedingung.', 'Q, Norm und epsilon sind modellabhängig festgelegt.', 'verified', 113),
(4316, '3.4100', 74, 'Toleranzbasierte Kohärenz einer gesamten Entwicklung', '\\forall k\\in\\{1,\\ldots,n\\}:\\left\\|Q(\\delta_k)-Q(\\delta_{k-1})\\right\\|\\leq\\varepsilon', '\\forall k\\in\\{1,\\ldots,n\\}:\\left\\|Q(\\delta_k)-Q(\\delta_{k-1})\\right\\|\\leq\\varepsilon\\qquad\\text{(3.4100)}', 'Die Toleranzbedingung gilt für jeden Entwicklungsschritt.', 'other', 'original', NULL, 'Globale Form der lokalen Toleranzbedingung.', 'Endliche Entwicklung.', 'verified', 113),
(4317, '3.4101', 74, 'Einfacher quantitativer Kohärenzgrad', 'K_{\\mathcal{C}}\\left(\\mathfrak{G}\\right)=\\frac{1}{m}\\sum_{r=1}^{m}C_r(\\mathfrak{G})', 'K_{\\mathcal{C}}\\left(\\mathfrak{G}\\right)=\\frac{1}{m}\\sum_{r=1}^{m}C_r(\\mathfrak{G})\\qquad\\text{(3.4101)}', 'Der Kohärenzgrad ist der Anteil erfüllter binärer Bedingungen.', 'metric', 'original', NULL, 'Definition eines einfachen quantitativen Kohärenzgrades.', 'm ist mindestens 1.', 'verified', 113),
(4318, '3.4102', 74, 'Wertebereich des Kohärenzgrades', '0\\leq K_{\\mathcal{C}}\\left(\\mathfrak{G}\\right)\\leq1', '0\\leq K_{\\mathcal{C}}\\left(\\mathfrak{G}\\right)\\leq1\\qquad\\text{(3.4102)}', 'Der Kohärenzgrad liegt zwischen 0 und 1.', 'derived', 'original', NULL, 'Folgt aus dem Mittelwert binärer Bedingungen.', 'm ist mindestens 1.', 'verified', 113),
(4319, '3.4103', 74, 'Gewichteter Kohärenzgrad', 'K_{\\mathcal{C}}^{(w)}\\left(\\mathfrak{G}\\right)=\\frac{\\sum_{r=1}^{m}w_rC_r(\\mathfrak{G})}{\\sum_{r=1}^{m}w_r},\\qquad w_r>0', 'K_{\\mathcal{C}}^{(w)}\\left(\\mathfrak{G}\\right)=\\frac{\\sum_{r=1}^{m}w_rC_r(\\mathfrak{G})}{\\sum_{r=1}^{m}w_r},\\qquad w_r>0\\qquad\\text{(3.4103)}', 'Der gewichtete Kohärenzgrad berücksichtigt unterschiedliche positive Gewichte der Bedingungen.', 'metric', 'original', NULL, 'Gewichtete Erweiterung von Gleichung (3.4101).', 'Alle Gewichte sind positiv.', 'verified', 113),
(4320, '3.4104', 74, 'Kohärenzgrad an Entwicklungsposition k', 'K_k=K_{\\mathcal{C}}\\left(\\mathfrak{G}^{(k)}\\right)', 'K_k=K_{\\mathcal{C}}\\left(\\mathfrak{G}^{(k)}\\right)\\qquad\\text{(3.4104)}', 'K_k ist der Kohärenzgrad der Struktur an Position k.', 'definition', 'original', NULL, 'Positionsabhängige Auswertung des Kohärenzgrades.', 'k besitzt keine Zeitbedeutung.', 'verified', 113),
(4321, '3.4105', 74, 'Lokaler Kohärenzverlust', 'K_k<K_{k-1}', 'K_k<K_{k-1}\\qquad\\text{(3.4105)}', 'Der Kohärenzgrad sinkt gegenüber der vorherigen Entwicklungsposition.', 'other', 'original', NULL, 'Definition eines lokalen Kohärenzverlusts.', 'K_k und K_{k-1} sind vergleichbar.', 'verified', 113),
(4322, '3.4106', 74, 'Kohärenzänderung', '\\Delta K_k=K_k-K_{k-1}', '\\Delta K_k=K_k-K_{k-1}\\qquad\\text{(3.4106)}', 'Delta K_k misst die Änderung des Kohärenzgrades zwischen zwei Entwicklungspositionen.', 'metric', 'original', NULL, 'Definition der diskreten Kohärenzänderung.', 'Keine Änderung pro Zeiteinheit.', 'verified', 113),
(4323, '3.4107', 74, 'Mindestkohärenz', 'K_{\\min}\\in[0,1]', 'K_{\\min}\\in[0,1]\\qquad\\text{(3.4107)}', 'K_min ist eine modellabhängig festgelegte Mindestkohärenz.', 'definition', 'original', NULL, 'Definition einer Akzeptanzschwelle.', 'Modellentscheidung.', 'verified', 113),
(4324, '3.4108', 74, 'Hinreichende Kohärenz', 'K_{\\mathcal{C}}\\left(\\mathfrak{G}\\right)\\geq K_{\\min}', 'K_{\\mathcal{C}}\\left(\\mathfrak{G}\\right)\\geq K_{\\min}\\qquad\\text{(3.4108)}', 'Eine Struktur gilt für den konkreten Zweck als hinreichend kohärent.', 'other', 'original', NULL, 'Vergleich des Kohärenzgrades mit der Modellschwelle.', 'K_min ist ausgewiesen.', 'verified', 113),
(4325, '3.4109', 74, 'Nicht übernommene universelle Kohärenzannahme', '\\forall\\mathfrak{G}_{\\mathcal{R},\\mathfrak{T}}:\\operatorname{Koh}_{\\mathcal{C}}\\left(\\mathfrak{G}_{\\mathcal{R},\\mathfrak{T}}\\right)=1', '\\forall\\mathfrak{G}_{\\mathcal{R},\\mathfrak{T}}:\\operatorname{Koh}_{\\mathcal{C}}\\left(\\mathfrak{G}_{\\mathcal{R},\\mathfrak{T}}\\right)=1\\qquad\\text{(3.4109)}', 'Die universelle Kohärenz aller funktionalen Strukturen wird ausdrücklich nicht vorausgesetzt.', 'other', 'original', NULL, 'Negativabgrenzung gegen ein zusätzliches Kohärenzaxiom.', 'Diese Formel wird nicht als Axiom oder Satz übernommen.', 'verified', 113),
(4326, '3.4110', 75, 'Zusammengesetzte Transformation zur Ordnungsbildung', 'T^{(n)}=T_n\\circ T_{n-1}\\circ\\cdots\\circ T_1', 'T^{(n)}=T_n\\circ T_{n-1}\\circ\\cdots\\circ T_1\\qquad\\text{(3.4110)}', 'Komposition einer endlichen Folge funktionaler Transformationen.', 'definition', 'literature', 59, 'Wiederaufnahme der Kompositionsstruktur aus Gleichung (3.4062).', 'Kompatible Definitions- und Zielbereiche.', 'verified', 114),
