(4466, '3.4250', 78, 'Kopplungsprädikat', '\\kappa_{XT}:\\mathcal{Z}_{F}\\times\\mathcal{Z}_{F}\\rightarrow\\{0,1\\}', '\\kappa_{XT}:\\mathcal{Z}_{F}\\times\\mathcal{Z}_{F}\\rightarrow\\{0,1\\}\\qquad\\text{(3.4250)}', 'Kopplungsprädikat.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4467, '3.4251', 78, 'Funktionale Raum-Zeit-Kopplungsrelation', '\\mathcal{K}_{XT}=\\left\\{(z_i,z_j)\\in\\mathcal{Z}_{F}\\times\\mathcal{Z}_{F}\\middle|\\kappa_{XT}(z_i,z_j)=1\\right\\}', '\\mathcal{K}_{XT}=\\left\\{(z_i,z_j)\\in\\mathcal{Z}_{F}\\times\\mathcal{Z}_{F}\\middle|\\kappa_{XT}(z_i,z_j)=1\\right\\}\\qquad\\text{(3.4251)}', 'Funktionale Raum-Zeit-Kopplungsrelation.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4468, '3.4252', 78, 'Funktionale Raum-Zeit-Kopplungsstruktur', '\\mathfrak{K}_{XT}=\\left(\\mathfrak{X}_{F},\\mathfrak{T}_{F},\\mathcal{K}_{XT}\\right)', '\\mathfrak{K}_{XT}=\\left(\\mathfrak{X}_{F},\\mathfrak{T}_{F},\\mathcal{K}_{XT}\\right)\\qquad\\text{(3.4252)}', 'Funktionale Raum-Zeit-Kopplungsstruktur.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4469, '3.4253', 78, 'Zugehörigkeitskriterium der Kopplungsrelation', '(z_i,z_j)\\in\\mathcal{K}_{XT}\\iff\\kappa_{XT}(z_i,z_j)=1', '(z_i,z_j)\\in\\mathcal{K}_{XT}\\iff\\kappa_{XT}(z_i,z_j)=1\\qquad\\text{(3.4253)}', 'Zugehörigkeitskriterium der Kopplungsrelation.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4470, '3.4254', 78, 'Minimale Bedingung der Erreichbarkeit', 'x_i\\preceq_{\\!F}x_j', 'x_i\\preceq_{\\!F}x_j\\qquad\\text{(3.4254)}', 'Minimale Bedingung der Erreichbarkeit.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4471, '3.4255', 78, 'Minimale Bedingung der Zeitordnung', '\\vartheta(x_i)\\leq_{\\mathbb{T}}\\vartheta(x_j)', '\\vartheta(x_i)\\leq_{\\mathbb{T}}\\vartheta(x_j)\\qquad\\text{(3.4255)}', 'Minimale Bedingung der Zeitordnung.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4472, '3.4256', 78, 'Minimale Bedingung räumlicher Verbindung', 'd_{\\mathrm{sp}}(x_i,x_j)<\\infty', 'd_{\\mathrm{sp}}(x_i,x_j)<\\infty\\qquad\\text{(3.4256)}', 'Minimale Bedingung räumlicher Verbindung.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4473, '3.4257', 78, 'Minimale Raum-Zeit-Kopplungsbedingung', '\\kappa_{XT}(z_i,z_j)=1\\iff\\left(x_i\\preceq_{\\!F}x_j\\right)\\land\\left(\\vartheta(x_i)\\leq_{\\mathbb{T}}\\vartheta(x_j)\\right)\\land\\left(d_{\\mathrm{sp}}(x_i,x_j)<\\infty\\right)', '\\kappa_{XT}(z_i,z_j)=1\\iff\\left(x_i\\preceq_{\\!F}x_j\\right)\\land\\left(\\vartheta(x_i)\\leq_{\\mathbb{T}}\\vartheta(x_j)\\right)\\land\\left(d_{\\mathrm{sp}}(x_i,x_j)<\\infty\\right)\\qquad\\text{(3.4257)}', 'Minimale Raum-Zeit-Kopplungsbedingung.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4474, '3.4258', 78, 'Funktionale Dauer eines Übergangs', '\\Delta t^{F}_{ij}=t^{F}_{j}-t^{F}_{i}', '\\Delta t^{F}_{ij}=t^{F}_{j}-t^{F}_{i}\\qquad\\text{(3.4258)}', 'Funktionale Dauer eines Übergangs.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4475, '3.4259', 78, 'Räumliche Distanz eines Übergangs', 'd_{\\mathrm{sp}}(x_i,x_j)', 'd_{\\mathrm{sp}}(x_i,x_j)\\qquad\\text{(3.4259)}', 'Räumliche Distanz eines Übergangs.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4476, '3.4260', 78, 'Funktionale räumliche Änderungsrate', 'v^{F}_{ij}=\\frac{d_{\\mathrm{sp}}(x_i,x_j)}{\\Delta t^{F}_{ij}},\\qquad\\Delta t^{F}_{ij}>0', 'v^{F}_{ij}=\\frac{d_{\\mathrm{sp}}(x_i,x_j)}{\\Delta t^{F}_{ij}},\\qquad\\Delta t^{F}_{ij}>0\\qquad\\text{(3.4260)}', 'Funktionale räumliche Änderungsrate.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4477, '3.4261', 78, 'Maximale funktionale Kopplungsrate', 'v^{F}_{\\max}>0', 'v^{F}_{\\max}>0\\qquad\\text{(3.4261)}', 'Maximale funktionale Kopplungsrate.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4478, '3.4262', 78, 'Beschränkung der funktionalen Kopplungsrate', 'v^{F}_{ij}\\leq v^{F}_{\\max}', 'v^{F}_{ij}\\leq v^{F}_{\\max}\\qquad\\text{(3.4262)}', 'Beschränkung der funktionalen Kopplungsrate.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4479, '3.4263', 78, 'Äquivalente Distanz-Dauer-Schranke', 'd_{\\mathrm{sp}}(x_i,x_j)\\leq v^{F}_{\\max}\\Delta t^{F}_{ij}', 'd_{\\mathrm{sp}}(x_i,x_j)\\leq v^{F}_{\\max}\\Delta t^{F}_{ij}\\qquad\\text{(3.4263)}', 'Äquivalente Distanz-Dauer-Schranke.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4480, '3.4264', 78, 'Funktionaler Vorwärtskopplungsbereich', '\\mathcal{C}^{+}_{F}(z_i)=\\left\\{z_j=(x_j,t_j^{F})\\in\\mathcal{Z}_{F}\\middle|t_j^{F}\\geq t_i^{F}\\land d_{\\mathrm{sp}}(x_i,x_j)\\leq v^{F}_{\\max}\\left(t_j^{F}-t_i^{F}\\right)\\right\\}', '\\mathcal{C}^{+}_{F}(z_i)=\\left\\{z_j=(x_j,t_j^{F})\\in\\mathcal{Z}_{F}\\middle|t_j^{F}\\geq t_i^{F}\\land d_{\\mathrm{sp}}(x_i,x_j)\\leq v^{F}_{\\max}\\left(t_j^{F}-t_i^{F}\\right)\\right\\}\\qquad\\text{(3.4264)}', 'Funktionaler Vorwärtskopplungsbereich.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4481, '3.4265', 78, 'Funktionaler Rückwärtskopplungsbereich', '\\mathcal{C}^{-}_{F}(z_i)=\\left\\{z_j=(x_j,t_j^{F})\\in\\mathcal{Z}_{F}\\middle|t_j^{F}\\leq t_i^{F}\\land d_{\\mathrm{sp}}(x_i,x_j)\\leq v^{F}_{\\max}\\left(t_i^{F}-t_j^{F}\\right)\\right\\}', '\\mathcal{C}^{-}_{F}(z_i)=\\left\\{z_j=(x_j,t_j^{F})\\in\\mathcal{Z}_{F}\\middle|t_j^{F}\\leq t_i^{F}\\land d_{\\mathrm{sp}}(x_i,x_j)\\leq v^{F}_{\\max}\\left(t_i^{F}-t_j^{F}\\right)\\right\\}\\qquad\\text{(3.4265)}', 'Funktionaler Rückwärtskopplungsbereich.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4482, '3.4266', 78, 'Unbeschränkte Raum-Zeit-Kopplungsrelation', '\\mathcal{K}_{XT}^{0}=\\left\\{(z_i,z_j)\\middle|x_i\\preceq_{\\!F}x_j\\land t_i^{F}\\leq_{\\mathbb{T}}t_j^{F}\\land d_{\\mathrm{sp}}(x_i,x_j)<\\infty\\right\\}', '\\mathcal{K}_{XT}^{0}=\\left\\{(z_i,z_j)\\middle|x_i\\preceq_{\\!F}x_j\\land t_i^{F}\\leq_{\\mathbb{T}}t_j^{F}\\land d_{\\mathrm{sp}}(x_i,x_j)<\\infty\\right\\}\\qquad\\text{(3.4266)}', 'Unbeschränkte Raum-Zeit-Kopplungsrelation.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4483, '3.4267', 78, 'Funktionale Zustandsbahn', '\\Gamma=\\left(x_0,x_1,\\ldots,x_n\\right)', '\\Gamma=\\left(x_0,x_1,\\ldots,x_n\\right)\\qquad\\text{(3.4267)}', 'Funktionale Zustandsbahn.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4484, '3.4268', 78, 'Zeitwerte einer funktionalen Bahn', 't_0^{F},t_1^{F},\\ldots,t_n^{F}', 't_0^{F},t_1^{F},\\ldots,t_n^{F}\\qquad\\text{(3.4268)}', 'Zeitwerte einer funktionalen Bahn.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4485, '3.4269', 78, 'Funktionale Raum-Zeit-Bahn', '\\Gamma_{XT}=\\left(z_0,z_1,\\ldots,z_n\\right),\\qquad z_k=\\left(x_k,t_k^{F}\\right)', '\\Gamma_{XT}=\\left(z_0,z_1,\\ldots,z_n\\right),\\qquad z_k=\\left(x_k,t_k^{F}\\right)\\qquad\\text{(3.4269)}', 'Funktionale Raum-Zeit-Bahn.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4486, '3.4270', 78, 'Lokale Kopplungszulässigkeit einer Bahn', '\\forall k\\in\\{1,\\ldots,n\\}:\\kappa_{XT}\\left(z_{k-1},z_k\\right)=1', '\\forall k\\in\\{1,\\ldots,n\\}:\\kappa_{XT}\\left(z_{k-1},z_k\\right)=1\\qquad\\text{(3.4270)}', 'Lokale Kopplungszulässigkeit einer Bahn.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4487, '3.4271', 78, 'Globales Raum-Zeit-Kopplungsprädikat', 'K_{XT}^{\\mathrm{glob}}:\\Gamma_{XT}\\rightarrow\\{0,1\\}', 'K_{XT}^{\\mathrm{glob}}:\\Gamma_{XT}\\rightarrow\\{0,1\\}\\qquad\\text{(3.4271)}', 'Globales Raum-Zeit-Kopplungsprädikat.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4488, '3.4272', 78, 'Globale Kopplungszulässigkeit', 'K_{XT}^{\\mathrm{glob}}\\left(\\Gamma_{XT}\\right)=1', 'K_{XT}^{\\mathrm{glob}}\\left(\\Gamma_{XT}\\right)=1\\qquad\\text{(3.4272)}', 'Globale Kopplungszulässigkeit.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4489, '3.4273', 78, 'Menge der Raum-Zeit-Kohärenzbedingungen', '\\mathcal{C}_{XT}=\\left\\{C_{XT,1},C_{XT,2},\\ldots,C_{XT,m}\\right\\}', '\\mathcal{C}_{XT}=\\left\\{C_{XT,1},C_{XT,2},\\ldots,C_{XT,m}\\right\\}\\qquad\\text{(3.4273)}', 'Menge der Raum-Zeit-Kohärenzbedingungen.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4490, '3.4274', 78, 'Raum-Zeit-Kohärenz', '\\operatorname{Koh}_{XT}\\left(\\mathfrak{K}_{XT}\\right)=1\\iff\\forall C_{XT,r}\\in\\mathcal{C}_{XT}:C_{XT,r}\\left(\\mathfrak{K}_{XT}\\right)=1', '\\operatorname{Koh}_{XT}\\left(\\mathfrak{K}_{XT}\\right)=1\\iff\\forall C_{XT,r}\\in\\mathcal{C}_{XT}:C_{XT,r}\\left(\\mathfrak{K}_{XT}\\right)=1\\qquad\\text{(3.4274)}', 'Raum-Zeit-Kohärenz.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4491, '3.4275', 78, 'Ratenbeschränkte Raum-Zeit-Kohärenz', 'd_{\\mathrm{sp}}(x_{k-1},x_k)\\leq v^{F}_{\\max}\\Delta t_k^{F}', 'd_{\\mathrm{sp}}(x_{k-1},x_k)\\leq v^{F}_{\\max}\\Delta t_k^{F}\\qquad\\text{(3.4275)}', 'Ratenbeschränkte Raum-Zeit-Kohärenz.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4492, '3.4276', 78, 'Mindestkohärenzgrad einer gekoppelten Entwicklung', 'K_{\\mathcal{C}}\\left(\\mathfrak{G}^{(k)}\\right)\\geq K_{\\min}', 'K_{\\mathcal{C}}\\left(\\mathfrak{G}^{(k)}\\right)\\geq K_{\\min}\\qquad\\text{(3.4276)}', 'Mindestkohärenzgrad einer gekoppelten Entwicklung.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4493, '3.4277', 78, 'Quantitativer Raum-Zeit-Kopplungsgrad', 'K_{XT}=\\frac{1}{m}\\sum_{r=1}^{m}C_{XT,r}', 'K_{XT}=\\frac{1}{m}\\sum_{r=1}^{m}C_{XT,r}\\qquad\\text{(3.4277)}', 'Quantitativer Raum-Zeit-Kopplungsgrad.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4494, '3.4278', 78, 'Wertebereich des Kopplungsgrades', '0\\leq K_{XT}\\leq1', '0\\leq K_{XT}\\leq1\\qquad\\text{(3.4278)}', 'Wertebereich des Kopplungsgrades.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4495, '3.4279', 78, 'Gewichteter Raum-Zeit-Kopplungsgrad', 'K_{XT}^{(w)}=\\frac{\\sum_{r=1}^{m}w_rC_{XT,r}}{\\sum_{r=1}^{m}w_r},\\qquad w_r>0', 'K_{XT}^{(w)}=\\frac{\\sum_{r=1}^{m}w_rC_{XT,r}}{\\sum_{r=1}^{m}w_r},\\qquad w_r>0\\qquad\\text{(3.4279)}', 'Gewichteter Raum-Zeit-Kopplungsgrad.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4496, '3.4280', 78, 'Lokaler Kopplungsgrad', 'K_{XT,k}=K_{XT}\\left(z_{k-1},z_k\\right)', 'K_{XT,k}=K_{XT}\\left(z_{k-1},z_k\\right)\\qquad\\text{(3.4280)}', 'Lokaler Kopplungsgrad.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4497, '3.4281', 78, 'Änderung des lokalen Kopplungsgrades', '\\Delta K_{XT,k}=K_{XT,k}-K_{XT,k-1}', '\\Delta K_{XT,k}=K_{XT,k}-K_{XT,k-1}\\qquad\\text{(3.4281)}', 'Änderung des lokalen Kopplungsgrades.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4498, '3.4282', 78, 'Vollständiger lokaler Kopplungsabbruch', 'K_{XT,k}=0', 'K_{XT,k}=0\\qquad\\text{(3.4282)}', 'Vollständiger lokaler Kopplungsabbruch.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117),
(4499, '3.4283', 78, 'Lokaler Raum-Zeit-Kopplungsbereich', '\\mathcal{U}_{XT}\\subseteq\\mathcal{Z}_{F}', '\\mathcal{U}_{XT}\\subseteq\\mathcal{Z}_{F}\\qquad\\text{(3.4283)}', 'Lokaler Raum-Zeit-Kopplungsbereich.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.17 übernommen.', 'Definitionen 3.3.5, 3.3.8, 3.3.9 und 3.3.10 sowie die jeweils ausdrücklich genannten Zusatzbedingungen.', 'verified', 117);
