(5447, '3.5231', 89, 'Einelementige Beobachtungsäquivalenzklasse', '[\\theta^\\ast]_{\\mathrm{obs}}=\\left\\{\\theta^\\ast\\right\\}', '[\\theta^\\ast]_{\\mathrm{obs}}=\\left\\{\\theta^\\ast\\right\\}\\qquad\\text{(3.5231)}', 'Einelementige Beobachtungsäquivalenzklasse.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.28 übernommen.', 'Definition 3.3.20 sowie die zuvor eingeführten Modell-, Empirie-, Invarianz- und Operationalisierungsstrukturen.', 'verified', 129),
(5448, '3.5232', 89, 'Globale Identifizierbarkeit einer Modellfamilie', '\\forall\\theta_1,\\theta_2\\in\\Theta:\\mathbf{P}_{F}(\\theta_1)=\\mathbf{P}_{F}(\\theta_2)\\Rightarrow\\theta_1=\\theta_2', '\\forall\\theta_1,\\theta_2\\in\\Theta:\\mathbf{P}_{F}(\\theta_1)=\\mathbf{P}_{F}(\\theta_2)\\Rightarrow\\theta_1=\\theta_2\\qquad\\text{(3.5232)}', 'Globale Identifizierbarkeit einer Modellfamilie.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.28 übernommen.', 'Definition 3.3.20 sowie die zuvor eingeführten Modell-, Empirie-, Invarianz- und Operationalisierungsstrukturen.', 'verified', 129),
(5449, '3.5233', 89, 'Nichtidentifizierbarkeit', '\\exists\\theta_1,\\theta_2\\in\\Theta:\\theta_1\\neq\\theta_2\\land\\mathbf{P}_{F}(\\theta_1)=\\mathbf{P}_{F}(\\theta_2)', '\\exists\\theta_1,\\theta_2\\in\\Theta:\\theta_1\\neq\\theta_2\\land\\mathbf{P}_{F}(\\theta_1)=\\mathbf{P}_{F}(\\theta_2)\\qquad\\text{(3.5233)}', 'Nichtidentifizierbarkeit.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.28 übernommen.', 'Definition 3.3.20 sowie die zuvor eingeführten Modell-, Empirie-, Invarianz- und Operationalisierungsstrukturen.', 'verified', 129),
(5450, '3.5234', 89, 'Mehrgliedrige Beobachtungsäquivalenzklasse', '\\left|[\\theta_1]_{\\mathrm{obs}}\\right|>1', '\\left|[\\theta_1]_{\\mathrm{obs}}\\right|>1\\qquad\\text{(3.5234)}', 'Mehrgliedrige Beobachtungsäquivalenzklasse.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.28 übernommen.', 'Definition 3.3.20 sowie die zuvor eingeführten Modell-, Empirie-, Invarianz- und Operationalisierungsstrukturen.', 'verified', 129),
(5451, '3.5235', 89, 'Lokale Parameterumgebung', 'U_{\\varepsilon}\\left(\\theta^\\ast\\right)\\subseteq\\Theta', 'U_{\\varepsilon}\\left(\\theta^\\ast\\right)\\subseteq\\Theta\\qquad\\text{(3.5235)}', 'Lokale Parameterumgebung.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.28 übernommen.', 'Definition 3.3.20 sowie die zuvor eingeführten Modell-, Empirie-, Invarianz- und Operationalisierungsstrukturen.', 'verified', 129),
