(5456, '3.5240', 89, 'Verschiedene vorzeicheninvertierte Parameterwerte', '\\theta\\neq-\\theta', '\\theta\\neq-\\theta\\qquad\\text{(3.5240)}', 'Verschiedene vorzeicheninvertierte Parameterwerte.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.28 übernommen.', 'Definition 3.3.20 sowie die zuvor eingeführten Modell-, Empirie-, Invarianz- und Operationalisierungsstrukturen.', 'verified', 129),
(5457, '3.5241', 89, 'Beobachtungsäquivalenzklasse bei Vorzeichensymmetrie', '[\\theta]_{\\mathrm{obs}}=\\left\\{\\theta,-\\theta\\right\\}', '[\\theta]_{\\mathrm{obs}}=\\left\\{\\theta,-\\theta\\right\\}\\qquad\\text{(3.5241)}', 'Beobachtungsäquivalenzklasse bei Vorzeichensymmetrie.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.28 übernommen.', 'Definition 3.3.20 sowie die zuvor eingeführten Modell-, Empirie-, Invarianz- und Operationalisierungsstrukturen.', 'verified', 129),
(5458, '3.5242', 89, 'Zusätzliche Vorzeichenbedingung', '\\theta\\geq0', '\\theta\\geq0\\qquad\\text{(3.5242)}', 'Zusätzliche Vorzeichenbedingung.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.28 übernommen.', 'Definition 3.3.20 sowie die zuvor eingeführten Modell-, Empirie-, Invarianz- und Operationalisierungsstrukturen.', 'verified', 129),
