(5466, '3.5250', 89, 'Rangdefizit der Sensitivitätsmatrix', '\\operatorname{rang}\\left(S(\\theta^\\ast)\\right)<p', '\\operatorname{rang}\\left(S(\\theta^\\ast)\\right)<p\\qquad\\text{(3.5250)}', 'Rangdefizit der Sensitivitätsmatrix.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.28 übernommen.', 'Definition 3.3.20 sowie die zuvor eingeführten Modell-, Empirie-, Invarianz- und Operationalisierungsstrukturen.', 'verified', 129),
(5467, '3.5251', 89, 'Nullrichtung der Sensitivitätsmatrix', 'S(\\theta^\\ast)v=0', 'S(\\theta^\\ast)v=0\\qquad\\text{(3.5251)}', 'Nullrichtung der Sensitivitätsmatrix.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.28 übernommen.', 'Definition 3.3.20 sowie die zuvor eingeführten Modell-, Empirie-, Invarianz- und Operationalisierungsstrukturen.', 'verified', 129),
(5468, '3.5252', 89, 'Fisher-Informationsmatrix', '\\mathcal{I}_{F}(\\theta)=\\mathbb{E}\\left[\\nabla_{\\theta}\\log p(Y\\mid\\theta)\\,\\nabla_{\\theta}\\log p(Y\\mid\\theta)^{\\mathsf{T}}\\right]', '\\mathcal{I}_{F}(\\theta)=\\mathbb{E}\\left[\\nabla_{\\theta}\\log p(Y\\mid\\theta)\\,\\nabla_{\\theta}\\log p(Y\\mid\\theta)^{\\mathsf{T}}\\right]\\qquad\\text{(3.5252)}', 'Fisher-Informationsmatrix.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.28 übernommen.', 'Definition 3.3.20 sowie die zuvor eingeführten Modell-, Empirie-, Invarianz- und Operationalisierungsstrukturen.', 'verified', 129),
(5469, '3.5253', 89, 'Singuläre Fisher-Informationsmatrix', '\\det\\left(\\mathcal{I}_{F}(\\theta)\\right)=0', '\\det\\left(\\mathcal{I}_{F}(\\theta)\\right)=0\\qquad\\text{(3.5253)}', 'Singuläre Fisher-Informationsmatrix.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.28 übernommen.', 'Definition 3.3.20 sowie die zuvor eingeführten Modell-, Empirie-, Invarianz- und Operationalisierungsstrukturen.', 'verified', 129),
