(5736, '3.5520', 91, 'Vektorielle Modellabbildung im Satz', '\\mathbf{Y}=f(\\mathbf{X})', '\\mathbf{Y}=f(\\mathbf{X})\\qquad\\text{(3.5520)}', 'Vektorielle Modellabbildung im Satz.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.30 übernommen.', 'Definition 3.3.22 sowie die zuvor eingeführten Empirie-, Stabilitäts-, Modell- und Operationalisierungsstrukturen.', 'verified', 132),
(5737, '3.5521', 91, 'Linearisierte Kovarianzfortpflanzung im Satz', '\\Sigma_Y\\approx J_f\\Sigma_XJ_f^{\\mathsf{T}}', '\\Sigma_Y\\approx J_f\\Sigma_XJ_f^{\\mathsf{T}}\\qquad\\text{(3.5521)}', 'Linearisierte Kovarianzfortpflanzung im Satz.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.30 übernommen.', 'Definition 3.3.22 sowie die zuvor eingeführten Empirie-, Stabilitäts-, Modell- und Operationalisierungsstrukturen.', 'verified', 132),
(5738, '3.5522', 91, 'Taylor-Näherung im Beweis', 'f(\\mathbf{X})\\approx f(\\boldsymbol{\\mu}_X)+J_f\\left(\\mathbf{X}-\\boldsymbol{\\mu}_X\\right)', 'f(\\mathbf{X})\\approx f(\\boldsymbol{\\mu}_X)+J_f\\left(\\mathbf{X}-\\boldsymbol{\\mu}_X\\right)\\qquad\\text{(3.5522)}', 'Taylor-Näherung im Beweis.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.30 übernommen.', 'Definition 3.3.22 sowie die zuvor eingeführten Empirie-, Stabilitäts-, Modell- und Operationalisierungsstrukturen.', 'verified', 132),
(5739, '3.5523', 91, 'Kovarianz des linearen Terms', '\\operatorname{Cov}\\left(\\mathbf{Y}\\right)\\approx\\operatorname{Cov}\\left(J_f\\left(\\mathbf{X}-\\boldsymbol{\\mu}_X\\right)\\right)', '\\operatorname{Cov}\\left(\\mathbf{Y}\\right)\\approx\\operatorname{Cov}\\left(J_f\\left(\\mathbf{X}-\\boldsymbol{\\mu}_X\\right)\\right)\\qquad\\text{(3.5523)}', 'Kovarianz des linearen Terms.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.30 übernommen.', 'Definition 3.3.22 sowie die zuvor eingeführten Empirie-, Stabilitäts-, Modell- und Operationalisierungsstrukturen.', 'verified', 132),
(5740, '3.5524', 91, 'Kovarianztransformation einer konstanten Matrix', '\\operatorname{Cov}\\left(J_f\\mathbf{X}\\right)=J_f\\operatorname{Cov}\\left(\\mathbf{X}\\right)J_f^{\\mathsf{T}}', '\\operatorname{Cov}\\left(J_f\\mathbf{X}\\right)=J_f\\operatorname{Cov}\\left(\\mathbf{X}\\right)J_f^{\\mathsf{T}}\\qquad\\text{(3.5524)}', 'Kovarianztransformation einer konstanten Matrix.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.30 übernommen.', 'Definition 3.3.22 sowie die zuvor eingeführten Empirie-, Stabilitäts-, Modell- und Operationalisierungsstrukturen.', 'verified', 132),
(5741, '3.5525', 91, 'Beweisergebnis der Kovarianzfortpflanzung', '\\Sigma_Y\\approx J_f\\Sigma_XJ_f^{\\mathsf{T}}', '\\Sigma_Y\\approx J_f\\Sigma_XJ_f^{\\mathsf{T}}\\qquad\\text{(3.5525)}', 'Beweisergebnis der Kovarianzfortpflanzung.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.30 übernommen.', 'Definition 3.3.22 sowie die zuvor eingeführten Empirie-, Stabilitäts-, Modell- und Operationalisierungsstrukturen.', 'verified', 132),
