(5763, '3.5547', 92, 'Positive Entscheidungskonsistenz', '\\operatorname{Kon}_{F}\\left(\\mathfrak{C}_{F}\\right)=1', '\\operatorname{Kon}_{F}\\left(\\mathfrak{C}_{F}\\right)=1\\qquad\\text{(3.5547)}', 'Positive Entscheidungskonsistenz.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.31 übernommen.', 'Definition 3.3.23 sowie die zuvor eingeführten Unsicherheits-, Stabilitäts-, Invarianz- und Empiriestrukturen.', 'verified', 133),
(5764, '3.5548', 92, 'Unsicherheitsintervall des Entscheidungswerts', 'I_Y=\\left[y-u_Y,y+u_Y\\right]', 'I_Y=\\left[y-u_Y,y+u_Y\\right]\\qquad\\text{(3.5548)}', 'Unsicherheitsintervall des Entscheidungswerts.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.31 übernommen.', 'Definition 3.3.23 sowie die zuvor eingeführten Unsicherheits-, Stabilitäts-, Invarianz- und Empiriestrukturen.', 'verified', 133),
(5765, '3.5549', 92, 'Eindeutige negative Entscheidung', 'y+u_Y<\\tau', 'y+u_Y<\\tau\\qquad\\text{(3.5549)}', 'Eindeutige negative Entscheidung.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.31 übernommen.', 'Definition 3.3.23 sowie die zuvor eingeführten Unsicherheits-, Stabilitäts-, Invarianz- und Empiriestrukturen.', 'verified', 133),
(5766, '3.5550', 92, 'Eindeutige positive Entscheidung', 'y-u_Y\\geq\\tau', 'y-u_Y\\geq\\tau\\qquad\\text{(3.5550)}', 'Eindeutige positive Entscheidung.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.31 übernommen.', 'Definition 3.3.23 sowie die zuvor eingeführten Unsicherheits-, Stabilitäts-, Invarianz- und Empiriestrukturen.', 'verified', 133),
(5767, '3.5551', 92, 'Überlappung des Schwellenwerts durch das Unsicherheitsintervall', 'y-u_Y<\\tau\\leq y+u_Y', 'y-u_Y<\\tau\\leq y+u_Y\\qquad\\text{(3.5551)}', 'Überlappung des Schwellenwerts durch das Unsicherheitsintervall.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.31 übernommen.', 'Definition 3.3.23 sowie die zuvor eingeführten Unsicherheits-, Stabilitäts-, Invarianz- und Empiriestrukturen.', 'verified', 133),
(5768, '3.5552', 92, 'Dreistufige Entscheidungsmenge', '\\mathfrak{C}_{3}=\\left\\{\\mathbf{negativ},\\mathbf{unsicher},\\mathbf{positiv}\\right\\}', '\\mathfrak{C}_{3}=\\left\\{\\mathbf{negativ},\\mathbf{unsicher},\\mathbf{positiv}\\right\\}\\qquad\\text{(3.5552)}', 'Dreistufige Entscheidungsmenge.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.31 übernommen.', 'Definition 3.3.23 sowie die zuvor eingeführten Unsicherheits-, Stabilitäts-, Invarianz- und Empiriestrukturen.', 'verified', 133),
(5769, '3.5553', 92, 'Dreistufige Entscheidungsregel', '\\mathcal{C}_{F}^{(3)}\\left(y,u_Y,\\tau\\right)=\\begin{cases}\\mathbf{negativ},&y+u_Y<\\tau,\\\\\\mathbf{positiv},&y-u_Y\\geq\\tau,\\\\\\mathbf{unsicher},&\\text{sonst}\\end{cases}', '\\mathcal{C}_{F}^{(3)}\\left(y,u_Y,\\tau\\right)=\\begin{cases}\\mathbf{negativ},&y+u_Y<\\tau,\\\\\\mathbf{positiv},&y-u_Y\\geq\\tau,\\\\\\mathbf{unsicher},&\\text{sonst}\\end{cases}\\qquad\\text{(3.5553)}', 'Dreistufige Entscheidungsregel.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.31 übernommen.', 'Definition 3.3.23 sowie die zuvor eingeführten Unsicherheits-, Stabilitäts-, Invarianz- und Empiriestrukturen.', 'verified', 133),
(5770, '3.5554', 92, 'Probabilistische positive Entscheidung', '\\mathcal{C}_{F}^{\\mathrm{prob}}(Y)=1\\iff\\Pr(Y\\geq\\tau)\\geq1-\\alpha', '\\mathcal{C}_{F}^{\\mathrm{prob}}(Y)=1\\iff\\Pr(Y\\geq\\tau)\\geq1-\\alpha\\qquad\\text{(3.5554)}', 'Probabilistische positive Entscheidung.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.31 übernommen.', 'Definition 3.3.23 sowie die zuvor eingeführten Unsicherheits-, Stabilitäts-, Invarianz- und Empiriestrukturen.', 'verified', 133),
(5771, '3.5555', 92, 'Probabilistische negative Entscheidung', '\\mathcal{C}_{F}^{\\mathrm{prob}}(Y)=0\\iff\\Pr(Y<\\tau)\\geq1-\\alpha', '\\mathcal{C}_{F}^{\\mathrm{prob}}(Y)=0\\iff\\Pr(Y<\\tau)\\geq1-\\alpha\\qquad\\text{(3.5555)}', 'Probabilistische negative Entscheidung.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.31 übernommen.', 'Definition 3.3.23 sowie die zuvor eingeführten Unsicherheits-, Stabilitäts-, Invarianz- und Empiriestrukturen.', 'verified', 133),
(5772, '3.5556', 92, 'Mehrklassige Entscheidungsmenge', '\\mathfrak{C}_{k}=\\left\\{C_1,C_2,\\ldots,C_k\\right\\}', '\\mathfrak{C}_{k}=\\left\\{C_1,C_2,\\ldots,C_k\\right\\}\\qquad\\text{(3.5556)}', 'Mehrklassige Entscheidungsmenge.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.31 übernommen.', 'Definition 3.3.23 sowie die zuvor eingeführten Unsicherheits-, Stabilitäts-, Invarianz- und Empiriestrukturen.', 'verified', 133),
(5773, '3.5557', 92, 'Geordnete Schwellenwertfolge', '\\tau_1<\\tau_2<\\cdots<\\tau_{k-1}', '\\tau_1<\\tau_2<\\cdots<\\tau_{k-1}\\qquad\\text{(3.5557)}', 'Geordnete Schwellenwertfolge.', 'definition', 'original', NULL, 'Aus dem Manuskriptabschnitt 3.3.31 übernommen.', 'Definition 3.3.23 sowie die zuvor eingeführten Unsicherheits-, Stabilitäts-, Invarianz- und Empiriestrukturen.', 'verified', 133);
