(8287, '3.7598', 103, 'Partielle Vergleichbarkeit', '\\Omega_i\\cap\\Omega_j\\neq\\varnothing\\land\\Omega_i\\neq\\Omega_j', '\\Omega_i\\cap\\Omega_j\\neq\\varnothing\\land\\Omega_i\\neq\\Omega_j\\qquad\\text{(3.7598)}', 'Nichtleere Schnittmenge bei nichtidentischen Gültigkeitsräumen.', 'definition', 'original', NULL, 'Definition 3.3.37.', 'Definierte Gültigkeitsräume.', 'verified', 157),
(8288, '3.7599', 103, 'Nichtvergleichbarkeit', '\\Omega_i\\cap\\Omega_j=\\varnothing', '\\Omega_i\\cap\\Omega_j=\\varnothing\\qquad\\text{(3.7599)}', 'Disjunkte funktionale Gültigkeitsräume.', 'definition', 'original', NULL, 'Definition 3.3.38.', 'Definierte Gültigkeitsräume.', 'verified', 157),
(8289, '3.7600', 103, 'Vergleichbarkeitsstatus Null', 'C(A_i,A_j)=0', 'C(A_i,A_j)=0\\qquad\\text{(3.7600)}', 'Kennzeichnung funktionaler Nichtvergleichbarkeit.', 'definition', 'original', NULL, 'Folgt aus Definition 3.3.38.', 'Leere Schnittmenge der Gültigkeitsräume.', 'verified', 157),
(8290, '3.7601', 103, 'Dreistufiger Vergleichbarkeitsoperator', '\\mathcal{C}:\\mathcal{A}\\times\\mathcal{A}\\longrightarrow\\{0,1,2\\}', '\\mathcal{C}:\\mathcal{A}\\times\\mathcal{A}\\longrightarrow\\{0,1,2\\}\\qquad\\text{(3.7601)}', 'Operator zur Klassifikation als nicht, partiell oder vollständig vergleichbar.', 'definition', 'original', NULL, 'Zusammenführung der Definitionen 3.3.36 bis 3.3.38.', 'Definierte Aussage- und Gültigkeitsräume.', 'verified', 157),
(8291, '3.7602', 103, 'Vergleichbarkeitsgrad', 'R_C=\\frac{\\mu(\\Omega_i\\cap\\Omega_j)}{\\mu(\\Omega_i\\cup\\Omega_j)}', 'R_C=\\frac{\\mu(\\Omega_i\\cap\\Omega_j)}{\\mu(\\Omega_i\\cup\\Omega_j)}\\qquad\\text{(3.7602)}', 'Quantitativer Grad der Überlappung zweier Gültigkeitsräume.', 'definition', 'original', NULL, 'Jaccard-artige Maßrelation auf den funktionalen Gültigkeitsräumen.', 'Geeignetes endliches Maß mu und nichtleere Vereinigung.', 'verified', 157),
(8292, '3.7603', 103, 'Wertebereich des Vergleichbarkeitsgrades', '0\\leq R_C\\leq1', '0\\leq R_C\\leq1\\qquad\\text{(3.7603)}', 'Normierter Wertebereich des Vergleichbarkeitsgrades.', 'derived', 'original', NULL, 'Folgt aus Schnittmenge als Teilmenge der Vereinigung.', 'Nichtnegative endliche Maße.', 'verified', 157),
(8293, '3.7604', 103, 'Voraussetzung Satz 3.3.26', '\\Omega_i=\\Omega_j', '\\Omega_i=\\Omega_j\\qquad\\text{(3.7604)}', 'Vollständige Vergleichbarkeit als Voraussetzung von Satz 3.3.26.', 'theorem', 'original', NULL, 'Satz 3.3.26.', 'Definierte Gültigkeitsräume.', 'verified', 157),
(8294, '3.7605', 103, 'Schluss Satz 3.3.26', 'R_C=1', 'R_C=1\\qquad\\text{(3.7605)}', 'Maximaler Vergleichbarkeitsgrad.', 'theorem', 'original', NULL, 'Satz 3.3.26.', 'Vollständige Vergleichbarkeit.', 'verified', 157),
(8295, '3.7606', 103, 'Identität von Schnittmenge und Vereinigung', '\\Omega_i\\cap\\Omega_j=\\Omega_i=\\Omega_i\\cup\\Omega_j', '\\Omega_i\\cap\\Omega_j=\\Omega_i=\\Omega_i\\cup\\Omega_j\\qquad\\text{(3.7606)}', 'Zwischenschritt des Beweises von Satz 3.3.26.', 'derived', 'original', NULL, 'Aus Omega_i=Omega_j.', 'Vollständige Vergleichbarkeit.', 'verified', 157),
(8296, '3.7607', 103, 'Beweis des maximalen Vergleichbarkeitsgrades', 'R_C=\\frac{\\mu(\\Omega_i)}{\\mu(\\Omega_i)}=1', 'R_C=\\frac{\\mu(\\Omega_i)}{\\mu(\\Omega_i)}=1\\qquad\\text{(3.7607)}', 'Schlussschritt des Beweises von Satz 3.3.26.', 'derived', 'original', NULL, 'Einsetzen der identischen Schnitt- und Vereinigungsmenge.', 'mu(Omega_i)>0.', 'verified', 157),
(8297, '3.7608', 103, 'Korollar zur vollständigen Vergleichbarkeit', 'R_C=1\\Longrightarrow\\Omega_i=\\Omega_j', 'R_C=1\\Longrightarrow\\Omega_i=\\Omega_j\\qquad\\text{(3.7608)}', 'Unter geeigneten Maßvoraussetzungen impliziert maximaler Vergleichbarkeitsgrad vollständige Vergleichbarkeit bis auf maßtheoretisch irrelevante Nullmengen.', '', 'original', NULL, 'Korollar 3.3.5.', 'Geeignetes Maß; bei rein maßtheoretischer Gleichheit ist die Gleichheit gegebenenfalls bis auf Nullmengen zu verstehen.', 'verified', 157),
(8298, '3.7609', 103, 'Aussagenpaar des Konsistenzoperators', 'A_i,\\;A_j\\in\\mathcal A', 'A_i,\\;A_j\\in\\mathcal A\\qquad\\text{(3.7609)}', 'Zwei wissenschaftliche Aussagen aus dem Aussagenraum.', 'definition', 'original', NULL, 'Ausgangspunkt des Konsistenzoperators.', 'Aussagenraum A definiert.', 'verified', 158);
INSERT INTO `equations` (`equation_id`, `equation_number`, `section_id`, `title`, `equation_latex`, `word_latex`, `plain_description`, `equation_type`, `provenance`, `source_id`, `derivation`, `assumptions`, `validation_status`, `created_revision_id`) VALUES
(8299, '3.7612', 103, 'Elementarer Konsistenzoperator', '\\mathfrak K:\\mathcal A\\times\\mathcal A\\times\\Omega\\longrightarrow\\{0,1\\}', '\\mathfrak K:\\mathcal A\\times\\mathcal A\\times\\Omega\\longrightarrow\\{0,1\\}\\qquad\\text{(3.7612)}', 'Elementarer zustandsbezogener Konsistenzoperator.', 'definition', 'original', NULL, 'Direkte Definition in 3.3.42.3.', 'Gemeinsame Domäne vorhanden.', 'verified', 158),
(8300, '3.7620', 103, 'Globale funktionale Konsistenz', '\\mathfrak K(A_i,A_j;z)=1\\qquad\\forall z\\in\\Omega_{ij}', '\\mathfrak K(A_i,A_j;z)=1\\qquad\\forall z\\in\\Omega_{ij}\\qquad\\text{(3.7620)}', 'Globale funktionale Konsistenz eines Aussagenpaares.', 'definition', 'original', NULL, 'Definition 3.3.40.', 'Gemeinsame Gültigkeitsdomäne Omega_ij.', 'verified', 158),
(8301, '3.7633', 103, 'Konsistenzgrad', 'R_K(A_i,A_j)=\\frac{\\mu\\left(\\Omega_{ij}^{K}\\right)}{\\mu\\left(\\Omega_{ij}\\right)}', 'R_K(A_i,A_j)=\\frac{\\mu\\left(\\Omega_{ij}^{K}\\right)}{\\mu\\left(\\Omega_{ij}\\right)}\\qquad\\text{(3.7633)}', 'Quantitativer Anteil des konsistenten Teils der gemeinsamen Gültigkeitsdomäne.', 'definition', 'original', NULL, 'Direkte Definition aus 3.3.42.9.', 'Positives endliches Maß der gemeinsamen Domäne.', 'verified', 158),
(8302, '3.7645', 103, 'Zerlegung der Konsistenzzustände', 'R_K+R_W+R_U=1', 'R_K+R_W+R_U=1\\qquad\\text{(3.7645)}', 'Normierte Zerlegung in Konsistenz-, Widerspruchs- und Unentscheidbarkeitsgrad.', 'derived', 'original', NULL, 'Aus disjunkter Zerlegung der gemeinsamen Gültigkeitsdomäne.', 'Vollständige Zerlegung der Domäne.', 'verified', 158),
(8303, '3.7653', 103, 'Prüfreihenfolge Vergleichbarkeit zu Konsistenz', '\\boxed{\\text{Vergleichbarkeit}\\rightarrow\\text{Konsistenz}}', '\\boxed{\\text{Vergleichbarkeit}\\rightarrow\\text{Konsistenz}}\\qquad\\text{(3.7653)}', 'Zwingende Prüfsequenz innerhalb der FRZK-Konsistenzarchitektur.', '', 'original', NULL, 'Aus der Vergleichbarkeitslogik.', 'Konsistenz nur bei vorhandener gemeinsamer Domäne.', 'verified', 158),
(8304, '3.7655', 103, 'Symmetrie der funktionalen Konsistenz', '\\mathfrak K(A_i,A_j;z)=\\mathfrak K(A_j,A_i;z)', '\\mathfrak K(A_i,A_j;z)=\\mathfrak K(A_j,A_i;z)\\qquad\\text{(3.7655)}', 'Kernaussage von Satz 3.3.27.', 'theorem', 'original', NULL, 'Satz 3.3.27.', 'Konsistenz durch gemeinsame Erfüllbarkeit definiert.', 'verified', 158),
(8305, '3.7668', 103, 'Reflexivität intern konsistenter Aussagen', 'K_{\\mathrm{int}}(A_i)=1\\Rightarrow\\mathfrak K(A_i,A_i;z)=1', 'K_{\\mathrm{int}}(A_i)=1\\Rightarrow\\mathfrak K(A_i,A_i;z)=1\\qquad\\text{(3.7668)}', 'Reflexivität gilt für intern konsistente Aussagen.', 'derived', 'original', NULL, 'Aus Definition 3.3.42.', 'Interne Aussagenkonsistenz.', 'verified', 158),
(8306, '3.7672', 103, 'Nichttransitivität der funktionalen Konsistenz', '\\left(A_i\\sim_K A_j\\land A_j\\sim_K A_k\\right)\\nRightarrow A_i\\sim_K A_k', '\\left(A_i\\sim_K A_j\\land A_j\\sim_K A_k\\right)\\nRightarrow A_i\\sim_K A_k\\qquad\\text{(3.7672)}', 'Funktionale Konsistenz ist im Allgemeinen nicht transitiv.', '', 'original', NULL, 'Aus dem Gegenbeispiel in 3.3.42.17.', 'Paarweise Konsistenzrelation.', 'verified', 158),
(8307, '3.7683', 103, 'Gemeinsame funktionale Konsistenz', 'K_F\\left(\\mathcal A_n\\right)=1\\Longleftrightarrow\\exists z\\in\\bigcap_{i=1}^{n}\\Omega_i:\\bigwedge_{i=1}^{n}A_i(z)=1', 'K_F\\left(\\mathcal A_n\\right)=1\\Longleftrightarrow\\exists z\\in\\bigcap_{i=1}^{n}\\Omega_i:\\bigwedge_{i=1}^{n}A_i(z)=1\\qquad\\text{(3.7683)}', 'Kernaussage von Definition 3.3.43.', 'definition', 'original', NULL, 'Definition 3.3.43.', 'Gemeinsame nichtleere Domäne.', 'verified', 158),
(8308, '3.7690', 103, 'Konsistenzreserve', 'M_K=d\\left(z,\\partial\\Omega_{\\mathcal A}^{K}\\right)', 'M_K=d\\left(z,\\partial\\Omega_{\\mathcal A}^{K}\\right)\\qquad\\text{(3.7690)}', 'Abstand eines Zustands zur Grenze des gemeinsamen Konsistenzkerns.', 'definition', 'original', NULL, 'Analog zur Stabilitätsreserve aus 3.3.41.', 'Definierter Konsistenzkern und Distanzbegriff.', 'verified', 158),
(8309, '3.7748', 103, 'Konfliktsignatur', '\\Sigma_W(A_i,A_j)=\\left(W_D,W_E,W_{\\mathrm{dir}},W_{\\mathrm{ind}},W_C,W_P,W_O,W_M,W_N,W_T,W_{\\mu M}\\right)', '\\Sigma_W(A_i,A_j)=\\left(W_D,W_E,W_{\\mathrm{dir}},W_{\\mathrm{ind}},W_C,W_P,W_O,W_M,W_N,W_T,W_{\\mu M}\\right)\\qquad\\text{(3.7748)}', 'Mehrdimensionale funktionale Konfliktsignatur.', 'definition', 'original', NULL, 'Zusammenführung der Konfliktklassen.', 'Definierte Konflikttypen.', 'verified', 158),
(8310, '3.7768', 103, 'Paarweise Konsistenzmatrix', '\\mathbf K=\\left[K_{ij}\\right]_{n\\times n}', '\\mathbf K=\\left[K_{ij}\\right]_{n\\times n}\\qquad\\text{(3.7768)}', 'Matrix aller paarweisen Konsistenzbeziehungen einer Aussagenmenge.', 'definition', 'original', NULL, 'Direkte Matrixdarstellung.', 'Endliche Aussagenmenge.', 'verified', 158),
(8311, '3.7779', 103, 'Konsistenzgraph', '\\mathcal G_K=\\left(V_K,E_K\\right)', '\\mathcal G_K=\\left(V_K,E_K\\right)\\qquad\\text{(3.7779)}', 'Graphische Darstellung paarweiser Konsistenzbeziehungen.', 'definition', 'original', NULL, 'Aus der Konsistenzmatrix abgeleitet.', 'Endliche Aussagenmenge.', 'verified', 158),
(8312, '3.7802', 103, 'Minimal inkonsistente Aussagenmenge', 'K_F(\\mathcal M_W)=0', 'K_F(\\mathcal M_W)=0\\qquad\\text{(3.7802)}', 'Inkonsistenzbedingung eines minimalen Konfliktkerns.', 'definition', 'original', NULL, 'Definition 3.3.46.', 'Gemeinsame Konsistenzprüfung.', 'verified', 158),
(8313, '3.7812', 103, 'Prüfsequenz der Konfliktdiagnose', '\\boxed{\\Omega\\rightarrow\\mathcal C\\rightarrow\\boldsymbol{\\theta}\\rightarrow\\mathcal O\\rightarrow\\mathcal M\\rightarrow E\\rightarrow A}', '\\boxed{\\Omega\\rightarrow\\mathcal C\\rightarrow\\boldsymbol{\\theta}\\rightarrow\\mathcal O\\rightarrow\\mathcal M\\rightarrow E\\rightarrow A}\\qquad\\text{(3.7812)}', 'Methodische Diagnosefolge vor einer inhaltlichen Aussagerevision.', '', 'original', NULL, 'Aus den Konfliktklassen abgeleitet.', 'Konfliktursachen werden stufenweise geprüft.', 'verified', 158),
(8314, '3.7839', 103, 'Technische und wissenschaftliche Gesamtkonsistenz', '\\mathbf K_{\\mathrm{total}}=\\left(K_{\\mathrm{tech}},K_{\\mathrm{sci}}\\right)', '\\mathbf K_{\\mathrm{total}}=\\left(K_{\\mathrm{tech}},K_{\\mathrm{sci}}\\right)\\qquad\\text{(3.7839)}', 'Getrennte Darstellung technischer und wissenschaftlicher Konsistenz.', 'definition', 'original', NULL, 'Aus Repository- und wissenschaftlicher Konsistenz.', 'Beide Prüfebenen werden unabhängig erfasst.', 'verified', 158),
(8315, '3.7863', 103, 'Erweiterte Konsistenzsignatur', '\\Sigma_K^{+}=\\left(K_A,K_D,K_E,K_T,K_P,K_C,K_{\\mathrm{repo}},R_K,R_W,R_U,C_K^{\\mathrm{cov}},M_K\\right)', '\\Sigma_K^{+}=\\left(K_A,K_D,K_E,K_T,K_P,K_C,K_{\\mathrm{repo}},R_K,R_W,R_U,C_K^{\\mathrm{cov}},M_K\\right)\\qquad\\text{(3.7863)}', 'Erweiterte mehrdimensionale Konsistenzsignatur.', 'definition', 'original', NULL, 'Zusammenführung der Konsistenzebenen.', 'Vollständige Prüfarchitektur bis 3.3.42.102.', 'verified', 158),
(8316, '3.7889', 103, 'Semantische Konsistenz', 'K_{\\mathrm{sem}}(A_i,A_j)=1', 'K_{\\mathrm{sem}}(A_i,A_j)=1\\qquad\\text{(3.7889)}', 'Kernaussage von Definition 3.3.47.', 'definition', 'original', NULL, 'Definition 3.3.47.', 'Explizite Symbol- und Bedeutungszuordnung.', 'verified', 158),
(8317, '3.7906', 103, 'Vollständiger mehrschichtiger Konsistenzgraph', '\\mathcal G_F^{K}=\\left(V,E_{\\mathrm{dep}},E_K,E_W\\right)', '\\mathcal G_F^{K}=\\left(V,E_{\\mathrm{dep}},E_K,E_W\\right)\\qquad\\text{(3.7906)}', 'Mehrschichtiger Graph aus Abhängigkeiten, Konsistenz- und Widerspruchsrelationen.', 'definition', 'original', NULL, 'Zusammenführung der zuvor definierten Graphstrukturen.', 'Definierte Knoten- und Kantenklassen.', 'verified', 158),
(8318, '3.7915', 103, 'Konfliktpropagation bei zwingender Abhängigkeit', 'K_{\\mathrm{int}}(A_i)=0\\land A_i\\rightarrow A_j\\Rightarrow V_{\\mathrm{der}}(A_j)=0', 'K_{\\mathrm{int}}(A_i)=0\\land A_i\\rightarrow A_j\\Rightarrow V_{\\mathrm{der}}(A_j)=0\\qquad\\text{(3.7915)}', 'Kernaussage von Satz 3.3.28.', 'theorem', 'original', NULL, 'Satz 3.3.28.', 'Zwingende Ableitungsabhängigkeit.', 'verified', 158),
(8319, '3.7950', 103, 'Reduktionskonsistenz', '\\mathcal R\\left(A_H\\right)\\sim_A A_L', '\\mathcal R\\left(A_H\\right)\\sim_A A_L\\qquad\\text{(3.7950)}', 'Funktionale Äquivalenz einer reduzierten höheren und einer einfacheren Theorieaussage.', 'definition', 'original', NULL, 'Direkte Definition aus 3.3.42.152.', 'Geeigneter gemeinsamer Grenzbereich.', 'verified', 158),
(8320, '3.7965', 103, 'Implikationsstruktur von Äquivalenz, Konsistenz und Vergleichbarkeit', 'A_i\\equiv A_j\\Rightarrow K_F(A_i,A_j)=1\\Rightarrow C(A_i,A_j)=1', 'A_i\\equiv A_j\\Rightarrow K_F(A_i,A_j)=1\\Rightarrow C(A_i,A_j)=1\\qquad\\text{(3.7965)}', 'Äquivalenz ist stärker als Konsistenz, Konsistenz stärker als bloße Vergleichbarkeit.', '', 'original', NULL, 'Zusammenfassung der Begriffsrelationen.', 'Geeignete gemeinsame Domäne.', 'verified', 158),
(8321, '3.7966', 103, 'Zwischenstand des Konsistenzsystems', '\\mathfrak C_F=\\left(\\mathcal C,\\mathfrak K,\\mathbf R_K,\\mathbf S_K,\\Sigma_W,\\mathcal G_F^K,\\mathcal K_W,\\Sigma_K^{+}\\right)', '\\mathfrak C_F=\\left(\\mathcal C,\\mathfrak K,\\mathbf R_K,\\mathbf S_K,\\Sigma_W,\\mathcal G_F^K,\\mathcal K_W,\\Sigma_K^{+}\\right)\\qquad\\text{(3.7966)}', 'Zwischenstand der bisher entwickelten Konsistenzarchitektur.', '', 'original', NULL, 'Zusammenführung von 3.3.42.3 bis 3.3.42.162.', 'Abschnitt 3.3.42 bleibt offen.', 'verified', 158),
(8322, '3.7610', 103, 'Gleichung 3.7610 – Abschnitt 3.3.42-P3', '\\text{Siehe vollständige Formel im Abschnitt 3.3.42, Gleichung (3.7610)}', '\\text{Siehe vollständige Formel im Abschnitt 3.3.42, Gleichung (3.7610)}\\qquad\\text{(3.7610)}', 'Repository-Registrierung der im Abschnittstext vollständig definierten Gleichung (3.7610).', 'derived', 'original', NULL, 'Aus dem vollständig ausgearbeiteten Abschnitt 3.3.42-P3 übernommen.', 'Teilstand 3.3.42-P3.', 'verified', 158),
