(9728, '3.8519', 104, 'Konsistenz impliziert nicht Kohärenz', 'K_F(A_i,A_j)=1\\nRightarrow C_F(A_i,A_j)>0', 'K_F(A_i,A_j)=1\\nRightarrow C_F(A_i,A_j)>0\\qquad\\text{(3.8519)}', 'Grundlegende Abgrenzung zwischen Konsistenz und Kohärenz.', '', 'original', NULL, 'Aus der begrifflichen Trennung von Widerspruchsfreiheit und funktionaler Kopplung.', 'Konsistenz- und Kohärenzbegriffe definiert.', 'verified', 162),
(9729, '3.8520', 104, 'Positive Kohärenz setzt Konsistenz voraus', 'C_F(A_i,A_j)>0\\Longrightarrow K_F(A_i,A_j)=1', 'C_F(A_i,A_j)>0\\Longrightarrow K_F(A_i,A_j)=1\\qquad\\text{(3.8520)}', 'Starke Kohärenzbedingung auf Basis konsistenter Beziehungen.', '', 'original', NULL, 'Vorbereitung von Definition 3.3.53 und Satz 3.3.30.', 'Gemeinsamer Gültigkeitsraum.', 'verified', 162),
(9730, '3.8533', 104, 'Lokale funktionale Kohärenz', 'C_F(X_i,X_j;z)>0\\Longleftrightarrow\\left[\\mathcal C(X_i,X_j;z)=1\\land K_F(X_i,X_j;z)=1\\land\\kappa_{ij}(z)>0\\right]', 'C_F(X_i,X_j;z)>0\\Longleftrightarrow\\left[\\mathcal C(X_i,X_j;z)=1\\land K_F(X_i,X_j;z)=1\\land\\kappa_{ij}(z)>0\\right]\\qquad\\text{(3.8533)}', 'Kernformel von Definition 3.3.53.', 'definition', 'original', NULL, 'Definition 3.3.53.', 'Vergleichbarkeit, Konsistenz und Kopplung.', 'verified', 162),
(9731, '3.8547', 104, 'Lokale Kohärenz impliziert lokale Konsistenz', 'C_F(X_i,X_j;z)>0\\Longrightarrow K_F(X_i,X_j;z)=1', 'C_F(X_i,X_j;z)>0\\Longrightarrow K_F(X_i,X_j;z)=1\\qquad\\text{(3.8547)}', 'Kernaussage von Satz 3.3.30.', 'theorem', 'original', NULL, 'Satz 3.3.30.', 'Definition 3.3.53 gilt.', 'verified', 162),
(9732, '3.8554', 104, 'Globale funktionale Kohärenz', '\\bar C_{ij}\\geq\\tau_C', '\\bar C_{ij}\\geq\\tau_C\\qquad\\text{(3.8554)}', 'Kernbedingung von Definition 3.3.54.', 'definition', 'original', NULL, 'Definition 3.3.54.', 'Begründete Kohärenzschwelle.', 'verified', 162),
(9733, '3.8583', 104, 'Kohärenzlänge', 'L_C=\\sup\\left\\{r:C_F\\left(X(x),X(x+r)\\right)\\geq\\tau_C\\right\\}', 'L_C=\\sup\\left\\{r:C_F\\left(X(x),X(x+r)\\right)\\geq\\tau_C\\right\\}\\qquad\\text{(3.8583)}', 'Charakteristische räumliche Distanz mit erhaltener Mindestkohärenz.', 'definition', 'original', NULL, 'Räumliche Kohärenz und Schwelle tau_C.', 'Geeignete räumliche Metrik.', 'verified', 162),
(9734, '3.8593', 104, 'Gerichtete funktionale Kohärenz', 'C_F^{\\rightarrow}(X_i,X_j)=C_{i\\rightarrow j}', 'C_F^{\\rightarrow}(X_i,X_j)=C_{i\\rightarrow j}\\qquad\\text{(3.8593)}', 'Kernformel von Definition 3.3.55.', 'definition', 'original', NULL, 'Definition 3.3.55.', 'Gerichtete funktionale Beziehung.', 'verified', 162),
(9735, '3.8600', 104, 'Kohärenzmatrix', '\\mathbf C=\\left[C_{ij}\\right]_{n\\times n}', '\\mathbf C=\\left[C_{ij}\\right]_{n\\times n}\\qquad\\text{(3.8600)}', 'Matrixdarstellung aller betrachteten Kohärenzbeziehungen.', 'definition', 'original', NULL, 'Direkte Matrixdarstellung.', 'Endliche Komponentenmenge.', 'verified', 162),
(9736, '3.8619', 104, 'Indirekte funktionale Kohärenz', 'C_F^{\\mathrm{ind}}(X_i,X_j)>0\\Longleftrightarrow\\exists p_{ij}:C(p_{ij})>0', 'C_F^{\\mathrm{ind}}(X_i,X_j)>0\\Longleftrightarrow\\exists p_{ij}:C(p_{ij})>0\\qquad\\text{(3.8619)}', 'Kernformel von Definition 3.3.56.', 'definition', 'original', NULL, 'Definition 3.3.56.', 'Kohärenzpfad und Pfadstärke definiert.', 'verified', 162),
(9737, '3.8632', 104, 'Systemkohärenzprofil', '\\mathbf P_C^{\\mathrm{sys}}=\\left(C_{\\mathrm{sys}},D_C,C_{\\mathrm{cluster}},R_C^{\\mathrm{reach}}\\right)', '\\mathbf P_C^{\\mathrm{sys}}=\\left(C_{\\mathrm{sys}},D_C,C_{\\mathrm{cluster}},R_C^{\\mathrm{reach}}\\right)\\qquad\\text{(3.8632)}', 'Mehrdimensionales Profil der Systemkohärenz.', 'definition', 'original', NULL, 'Zusammenführung mittlerer Kohärenz, Dichte, Cluster- und Reichweiteninformation.', 'Definierte Teilgrößen.', 'verified', 162),
(9738, '3.8650', 104, 'Kohärenzreserve', 'M_C=d\\left(z,\\partial\\Omega_C\\right)', 'M_C=d\\left(z,\\partial\\Omega_C\\right)\\qquad\\text{(3.8650)}', 'Abstand eines Zustands zur Grenze der Kohärenzdomäne.', 'definition', 'original', NULL, 'Analog zu Stabilitäts- und Konsistenzreserve.', 'Kohärenzdomäne und Distanzbegriff definiert.', 'verified', 162),
(9739, '3.8669', 104, 'Kohärenzoperationalisierung', '\\mathcal O_C:\\mathcal D\\rightarrow[0,1]', '\\mathcal O_C:\\mathcal D\\rightarrow[0,1]\\qquad\\text{(3.8669)}', 'Kernformel von Definition 3.3.57.', 'definition', 'original', NULL, 'Definition 3.3.57.', 'Explizite Datenbasis und Operationalisierung.', 'verified', 162),
(9740, '3.8683', 104, 'Kohärenzerhaltende Transformation', 'T\\in\\operatorname{Pres}(C_F)', 'T\\in\\operatorname{Pres}(C_F)\\qquad\\text{(3.8683)}', 'Kennzeichnung kohärenzerhaltender Transformationen.', 'definition', 'original', NULL, 'Aus Invarianz der betrachteten Kohärenzrelation.', 'Transformation und Kohärenzrelation definiert.', 'verified', 162),
(9741, '3.8695', 104, 'Erste Kohärenzsignatur', '\\Sigma_C=\\left(R_C,R_{\\Omega}^{C},I_C,T_C,L_C,M_C,A_C,D_C,U_C\\right)', '\\Sigma_C=\\left(R_C,R_{\\Omega}^{C},I_C,T_C,L_C,M_C,A_C,D_C,U_C\\right)\\qquad\\text{(3.8695)}', 'Erste mehrdimensionale Kohärenzsignatur.', 'definition', 'original', NULL, 'Zusammenführung der bis 3.3.43.99 entwickelten Kohärenzgrößen.', 'Definierte Teilkomponenten.', 'verified', 162),
(9742, '3.8696', 104, 'Grundbedingung funktionaler Kohärenz', '\\boxed{\\text{Vergleichbarkeit}+\\text{Konsistenz}+\\text{funktionale Kopplung}}', '\\boxed{\\text{Vergleichbarkeit}+\\text{Konsistenz}+\\text{funktionale Kopplung}}\\qquad\\text{(3.8696)}', 'Didaktisch und methodisch verdichtete Grundbedingung des Kohärenzbegriffs.', '', 'original', NULL, 'Zusammenfassung des bisherigen Abschnitts.', 'Vergleichbarkeit, Konsistenz und Kopplung definiert.', 'verified', 162),
(9743, '3.8697', 104, 'Grundstruktur funktionaler Kohärenz', 'C_F=\\mathcal F_C\\left(\\mathcal C,K_F,\\kappa,\\Omega,t,x,\\mathcal O_C\\right)', 'C_F=\\mathcal F_C\\left(\\mathcal C,K_F,\\kappa,\\Omega,t,x,\\mathcal O_C\\right)\\qquad\\text{(3.8697)}', 'Zwischenstand der mathematischen Grundstruktur funktionaler Kohärenz.', '', 'original', NULL, 'Zusammenführung von Vergleichbarkeit, Konsistenz, Kopplung, Domäne, Raum, Zeit und Operationalisierung.', 'Abschnitt 3.3.43 bleibt offen.', 'verified', 162),
