(10266, '3.8950', 104, 'Axiomprüfstruktur', '\\mathcal P_A=\\left(N_A,I_A,M_A,D_A,K_A,E_A\\right)', '\\mathcal P_A=\\left(N_A,I_A,M_A,D_A,K_A,E_A\\right)\\qquad\\text{(3.8950)}', 'Prüfstruktur für Notwendigkeit, Unabhängigkeit, Minimalität, Nichtableitbarkeit, Konsistenz und Offenheit.', 'definition', 'original', NULL, 'Aus den Anforderungen an die systematische Primäraxiomprüfung.', 'Kandidaten A, B und C sind definiert.', 'verified', 164),
(10267, '3.8954', 104, 'Kohärenzaxiom-Kandidat A', 'A_C^{(A)}:\\exists(X_i,X_j,z):C_F(X_i,X_j;z)>0', 'A_C^{(A)}:\\exists(X_i,X_j,z):C_F(X_i,X_j;z)>0\\qquad\\text{(3.8954)}', 'Schwächster ursprünglicher Kohärenzaxiom-Kandidat.', '', 'original', NULL, 'Übernahme des in P2 eingeführten Kandidaten A in die systematische Prüfung.', 'Positive funktionale Kohärenz ist definiert.', 'verified', 164),
(10268, '3.8958', 104, 'Definitionsstruktur lokaler Kohärenz', 'C_F>0\\Longleftrightarrow\\mathcal C=1\\land K_F=1\\land\\kappa>0', 'C_F>0\\Longleftrightarrow\\mathcal C=1\\land K_F=1\\land\\kappa>0\\qquad\\text{(3.8958)}', 'Verwendete Definitionsstruktur zur Nichtableitbarkeitsprüfung.', 'definition', 'original', NULL, 'Aus Definition 3.3.53.', 'Vergleichbarkeit, Konsistenz und Kopplung definiert.', 'verified', 164),
(10269, '3.8965', 104, 'Nichtableitbarkeit von Kandidat A', 'D_A\\left(A_C^{(A)}\\right)=1', 'D_A\\left(A_C^{(A)}\\right)=1\\qquad\\text{(3.8965)}', 'Zwischenresultat: Kandidat A ist aus Definitionen und Konsistenzarchitektur nicht ableitbar.', '', 'original', NULL, 'Aus kohärenzfreien und konsistent-kohärenzfreien Gegenmodellen.', 'Bisherige Axiomatik erzwingt keine positive Kopplung.', 'verified', 164),
(10270, '3.8966', 104, 'Kohärenzaxiom-Kandidat B', 'A_C^{(B)}:\\forall z\\in\\Omega_F^{\\mathrm{phys}}\\;\\exists(X_i,X_j):C_F(X_i,X_j;z)>0', 'A_C^{(B)}:\\forall z\\in\\Omega_F^{\\mathrm{phys}}\\;\\exists(X_i,X_j):C_F(X_i,X_j;z)>0\\qquad\\text{(3.8966)}', 'Stärkerer Kandidat mit positiver Kohärenz in jedem physikalischen Zustand.', '', 'original', NULL, 'Systematische Prüfung von Kandidat B.', 'Physikalischer Zustandsraum definiert.', 'verified', 164),
(10271, '3.8976', 104, 'Kohärenzaxiom-Kandidat C', 'A_C^{(C)}:C_{\\mathrm{sys}}(z)\\geq\\tau_C\\qquad\\forall z\\in\\Omega_F', 'A_C^{(C)}:C_{\\mathrm{sys}}(z)\\geq\\tau_C\\qquad\\forall z\\in\\Omega_F\\qquad\\text{(3.8976)}', 'Stärkster ursprünglicher Kandidat mit globaler Mindestkohärenz.', '', 'original', NULL, 'Systematische Prüfung von Kandidat C.', 'Systemkohärenz und Schwelle tau_C definiert.', 'verified', 164),
(10272, '3.8981', 104, 'Vorläufige Ablehnung von Kandidat C', 'A_C^{(C)}\\notin\\mathfrak A_{F,\\mathrm{prim}}^{\\mathrm{vorl}}', 'A_C^{(C)}\\notin\\mathfrak A_{F,\\mathrm{prim}}^{\\mathrm{vorl}}\\qquad\\text{(3.8981)}', 'Kandidat C wird wegen übermäßiger Stärke und Operationalisierungsabhängigkeit vorläufig nicht als Primäraxiom verwendet.', '', 'original', NULL, 'Aus Schwellenabhängigkeit, Zirkularitätsgefahr und Einschränkung offener Dynamik.', 'Primäraxiomatik soll minimal bleiben.', 'verified', 164),
(10273, '3.8989', 104, 'Vorläufiger Unabhängigkeitsbefund Kandidat A', 'I_A\\left(A_C^{(A)}\\right)=1', 'I_A\\left(A_C^{(A)}\\right)=1\\qquad\\text{(3.8989)}', 'Vorläufige Unabhängigkeit von Kandidat A gegenüber der bisherigen Primäraxiomatik.', '', 'original', NULL, 'Aus Nullkopplungsmodell und positiv gekoppeltem Vergleichsmodell.', 'Vollständige Primäraxiomliste muss weiterhin explizit gegengeprüft werden.', 'verified', 164),
(10274, '3.8990', 104, 'Konsistenzbedingung des neuen Axiomkandidaten', 'K_F\\left(\\mathfrak A_{F,\\mathrm{prim}}^{-C}\\cup\\{A_C^{(A)}\\}\\right)=1', 'K_F\\left(\\mathfrak A_{F,\\mathrm{prim}}^{-C}\\cup\\{A_C^{(A)}\\}\\right)=1\\qquad\\text{(3.8990)}', 'Konsistenzanforderung für die Erweiterung der Primäraxiomatik.', '', 'original', NULL, 'Aus der allgemeinen Konsistenzarchitektur.', 'Bisherige Primäraxiomatik definiert.', 'verified', 164),
(10275, '3.9024', 104, 'Funktional relevante Teilstruktur', 'R_F(\\mathcal S^{\\prime})=1\\Longleftrightarrow F(\\mathcal S_F)\\neq F(\\mathcal S_F\\setminus\\mathcal S^{\\prime})', 'R_F(\\mathcal S^{\\prime})=1\\Longleftrightarrow F(\\mathcal S_F)\\neq F(\\mathcal S_F\\setminus\\mathcal S^{\\prime})\\qquad\\text{(3.9024)}', 'Kernformel von Definition 3.3.65.', 'definition', 'original', NULL, 'Definition 3.3.65.', 'Systemfunktion und Teilstruktur definiert.', 'verified', 164),
(10276, '3.9025', 104, 'Kohärenzaxiom-Kandidat A+', 'A_C^{(A+)}:\\exists\\mathcal S_C:C_F(\\mathcal S_C)>0\\land R_F(\\mathcal S_C)=1', 'A_C^{(A+)}:\\exists\\mathcal S_C:C_F(\\mathcal S_C)>0\\land R_F(\\mathcal S_C)=1\\qquad\\text{(3.9025)}', 'Präzisierter Kandidat mit Bindung an eine funktional relevante Teilstruktur.', '', 'original', NULL, 'Aus der Kritik an bloßer Marginalkohärenz von Kandidat A.', 'Funktionale Relevanz ist kohärenzunabhängig definiert.', 'verified', 164),
(10277, '3.9046', 104, 'Modellweite Existenz relevanter Kohärenz', 'A_C^{(A+M)}:\\exists z\\in\\Omega_F\\;\\exists\\mathcal S_C(z):R_F(\\mathcal S_C)=1\\land C_F(\\mathcal S_C)>0', 'A_C^{(A+M)}:\\exists z\\in\\Omega_F\\;\\exists\\mathcal S_C(z):R_F(\\mathcal S_C)=1\\land C_F(\\mathcal S_C)>0\\qquad\\text{(3.9046)}', 'Schwächste A+-Variante auf Modellebene.', '', 'original', NULL, 'Aus der Quantorprüfung modellweit, trajektorienweit und zustandsweit.', 'Zustandsraum und funktionale Relevanz definiert.', 'verified', 164),
(10278, '3.9051', 104, 'Kohärenzaxiom-Kandidat D', '\\boxed{A_C^{(D)}:\\exists z\\in\\Omega_F\\;\\exists\\mathcal S_C\\subseteq\\mathcal S_F:R_F(\\mathcal S_C)=1\\land C_F(\\mathcal S_C;z)>0.}', '\\boxed{A_C^{(D)}:\\exists z\\in\\Omega_F\\;\\exists\\mathcal S_C\\subseteq\\mathcal S_F:R_F(\\mathcal S_C)=1\\land C_F(\\mathcal S_C;z)>0.}\\qquad\\text{(3.9051)}', 'Neu benannter funktional relevanter Existenzkohärenz-Kandidat D.', '', 'original', NULL, 'Aus Kandidat A+M.', 'Funktionale Relevanz ist nicht durch Kohärenz selbst definiert.', 'verified', 164),
(10279, '3.9052', 104, 'Stärkeordnung der Kohärenzaxiom-Kandidaten', 'A_C^{(C)}\\Rightarrow A_C^{(B)}\\Rightarrow A_C^{(D)}\\Rightarrow A_C^{(A)}', 'A_C^{(C)}\\Rightarrow A_C^{(B)}\\Rightarrow A_C^{(D)}\\Rightarrow A_C^{(A)}\\qquad\\text{(3.9052)}', 'Logische Stärkeordnung der vier betrachteten Kohärenzaxiom-Kandidaten.', '', 'original', NULL, 'Aus den jeweiligen Quantor- und Relevanzbedingungen.', 'Geeignete Systemdefinitionen vorausgesetzt.', 'verified', 164),
(10280, '3.9054', 104, 'Vorläufig bevorzugter Kohärenzaxiom-Kandidat', '\\boxed{A_C^{(D)}:\\exists z\\in\\Omega_F\\;\\exists\\mathcal S_C\\subseteq\\mathcal S_F:R_F(\\mathcal S_C)=1\\land C_F(\\mathcal S_C;z)>0.}', '\\boxed{A_C^{(D)}:\\exists z\\in\\Omega_F\\;\\exists\\mathcal S_C\\subseteq\\mathcal S_F:R_F(\\mathcal S_C)=1\\land C_F(\\mathcal S_C;z)>0.}\\qquad\\text{(3.9054)}', 'Vorläufiges Ergebnis der systematischen Axiomprüfung in P3.', '', 'original', NULL, 'Kandidat D bietet derzeit den besten Ausgleich aus Minimalität, funktionaler Relevanz und dynamischer Offenheit.', 'Noch nicht endgültig zum Primäraxiom erhoben.', 'verified', 164),
(10281, '3.8951', 104, 'Gleichung 3.8951 – Abschnitt 3.3.43-P3', '\\text{Siehe vollständige Formel im Abschnitt 3.3.43, Gleichung (3.8951)}', '\\text{Siehe vollständige Formel im Abschnitt 3.3.43, Gleichung (3.8951)}\\qquad\\text{(3.8951)}', 'Repository-Registrierung der im Abschnittstext vollständig definierten Gleichung (3.8951).', 'derived', 'original', NULL, 'Aus dem vollständig ausgearbeiteten Abschnitt 3.3.43-P3 übernommen.', 'Teilstand 3.3.43-P3.', 'verified', 164),
