(10423, '3.9070', 104, 'Erweiterte Primäraxiomatik mit Kandidat D', '\\mathfrak A_F^{1}=\\mathfrak A_F^{0}\\cup\\left\\{A_C^{(D)}\\right\\}', '\\mathfrak A_F^{1}=\\mathfrak A_F^{0}\\cup\\left\\{A_C^{(D)}\\right\\}\\qquad\\text{(3.9070)}', 'Erweiterung der bisherigen Primäraxiomatik um den Kohärenzaxiom-Kandidaten D.', 'definition', 'original', NULL, 'Aus der bisherigen Primäraxiomatik und Kandidat D.', 'Kandidat D ist definiert und unabhängig geprüft.', 'verified', 166),
(10424, '3.9071', 104, 'Konsistenzforderung der erweiterten Primäraxiomatik', '\\operatorname{Cons}\\left(\\mathfrak A_F^{1}\\right)=1', '\\operatorname{Cons}\\left(\\mathfrak A_F^{1}\\right)=1\\qquad\\text{(3.9071)}', 'Konsistenzforderung für die um Kandidat D erweiterte Primäraxiomatik.', '', 'original', NULL, 'Aus der allgemeinen Konsistenzprüfung von Axiomensystemen.', 'Erweiterte Primäraxiomatik definiert.', 'verified', 166),
(10425, '3.9072', 104, 'Existenz eines gemeinsamen Modells', '\\exists\\mathcal M:\\mathcal M\\models\\mathfrak A_F^{1}', '\\exists\\mathcal M:\\mathcal M\\models\\mathfrak A_F^{1}\\qquad\\text{(3.9072)}', 'Modelltheoretische Existenzbedingung für die Konsistenz der erweiterten Primäraxiomatik.', '', 'original', NULL, 'Aus der Konsistenzprüfung.', 'Ein erfüllendes Modell muss existieren.', 'verified', 166),
(10426, '3.9074', 104, 'Erfüllendes Modell M plus', '\\mathcal M_{+}\\models\\mathfrak A_F^{1}', '\\mathcal M_{+}\\models\\mathfrak A_F^{1}\\qquad\\text{(3.9074)}', 'Das positiv kohärente Vergleichsmodell erfüllt die erweiterte Primäraxiomatik.', '', 'original', NULL, 'Aus der Konstruktion von M plus.', 'M plus erfüllt die bisherigen Axiome und Kandidat D.', 'verified', 166),
(10427, '3.9076', 104, 'Kein direkter Widerspruch', '\\mathfrak A_F^{1}\\nvdash\\bot', '\\mathfrak A_F^{1}\\nvdash\\bot\\qquad\\text{(3.9076)}', 'Die erweiterte Primäraxiomatik erzeugt keinen direkten logischen Widerspruch.', '', 'original', NULL, 'Aus der Existenz mindestens eines erfüllenden Modells.', 'Modell M plus existiert.', 'verified', 166),
(10428, '3.9077', 104, 'Vereinbarkeit mit funktionaler Konsistenz', 'K_F\\land A_C^{(D)}\\not\\Rightarrow\\bot', 'K_F\\land A_C^{(D)}\\not\\Rightarrow\\bot\\qquad\\text{(3.9077)}', 'Funktionale Konsistenz und Kandidat D sind miteinander vereinbar.', '', 'original', NULL, 'Aus der Trennung zwischen Konsistenz und positiver funktionaler Kohärenz.', 'Konsistenz- und Kohärenzbegriffe sind getrennt definiert.', 'verified', 166),
(10429, '3.9078', 104, 'Existenzielle Kohärenzforderung', '\\exists z:C_F>0', '\\exists z:C_F>0\\qquad\\text{(3.9078)}', 'Kandidat D fordert nur die Existenz mindestens eines Zustands mit positiver Kohärenz.', '', 'original', NULL, 'Aus Kandidat D.', 'Existenzquantor über zulässige Zustände.', 'verified', 166),
(10430, '3.9079', 104, 'Keine universelle Kohärenzforderung', '\\forall z:C_F>0', '\\forall z:C_F>0\\qquad\\text{(3.9079)}', 'Diese universelle Kohärenzforderung folgt nicht aus Kandidat D.', '', 'original', NULL, 'Gegenüberstellung zur existenziellen Quantorstruktur von Kandidat D.', 'Kandidat D ist nur existenziell formuliert.', 'verified', 166),
(10431, '3.9080', 104, 'Zulässiger kohärenzfreier Zustand', 'C_F=0', 'C_F=0\\qquad\\text{(3.9080)}', 'Zustände ohne positive Kohärenz bleiben unter Kandidat D zulässig.', '', 'original', NULL, 'Aus der nichtuniversellen Quantorstruktur.', 'Mindestens ein anderer Zustand darf Kandidat D erfüllen.', 'verified', 166),
(10432, '3.9081', 104, 'Keine Kohärenzerhaltung als Axiomfolge', '\\frac{dC_F}{dt}=0', '\\frac{dC_F}{dt}=0\\qquad\\text{(3.9081)}', 'Zeitliche Kohärenzerhaltung wird durch Kandidat D nicht erzwungen.', '', 'original', NULL, 'Aus der dynamischen Offenheit von Kandidat D.', 'Keine Erhaltungsbedingung im Axiom.', 'verified', 166),
(10433, '3.9082', 104, 'Zunehmende Kohärenz bleibt zulässig', '\\frac{dC_F}{dt}>0', '\\frac{dC_F}{dt}>0\\qquad\\text{(3.9082)}', 'Kohärenzentstehung oder Kohärenzzunahme bleibt mit Kandidat D vereinbar.', '', 'original', NULL, 'Aus der fehlenden Erhaltungsforderung.', 'Dynamische Kohärenz zugelassen.', 'verified', 166),
(10434, '3.9083', 104, 'Abnehmende Kohärenz bleibt zulässig', '\\frac{dC_F}{dt}<0', '\\frac{dC_F}{dt}<0\\qquad\\text{(3.9083)}', 'Kohärenzverlust oder Kohärenzzerfall bleibt mit Kandidat D vereinbar.', '', 'original', NULL, 'Aus der fehlenden Erhaltungsforderung.', 'Dynamische Kohärenz zugelassen.', 'verified', 166);
INSERT INTO `equations` (`equation_id`, `equation_number`, `section_id`, `title`, `equation_latex`, `word_latex`, `plain_description`, `equation_type`, `provenance`, `source_id`, `derivation`, `assumptions`, `validation_status`, `created_revision_id`) VALUES
(10435, '3.9084', 104, 'Ergebnis der Konsistenzprüfung von Kandidat D', 'K_A\\left(A_C^{(D)}\\right)=1', 'K_A\\left(A_C^{(D)}\\right)=1\\qquad\\text{(3.9084)}', 'Kandidat D erfüllt die Konsistenzanforderung gegenüber der bisherigen Primäraxiomatik.', '', 'original', NULL, 'Aus Modellexistenz, Widerspruchsfreiheit und dynamischer Vereinbarkeit.', 'Unabhängigkeit wurde zuvor in P4 geprüft.', 'verified', 166),
(10436, '3.9073', 104, 'Gleichung 3.9073 – Abschnitt 3.3.43-P5', '\\text{Siehe vollständige Formel im Abschnitt 3.3.43, Gleichung (3.9073)}', '\\text{Siehe vollständige Formel im Abschnitt 3.3.43, Gleichung (3.9073)}\\qquad\\text{(3.9073)}', 'Repository-Registrierung der im Abschnittstext vollständig definierten Gleichung (3.9073).', 'derived', 'original', NULL, 'Aus dem vollständig ausgearbeiteten Abschnitt 3.3.43-P5 übernommen.', 'Teilstand 3.3.43-P5.', 'verified', 166),
(10437, '3.9075', 104, 'Gleichung 3.9075 – Abschnitt 3.3.43-P5', '\\text{Siehe vollständige Formel im Abschnitt 3.3.43, Gleichung (3.9075)}', '\\text{Siehe vollständige Formel im Abschnitt 3.3.43, Gleichung (3.9075)}\\qquad\\text{(3.9075)}', 'Repository-Registrierung der im Abschnittstext vollständig definierten Gleichung (3.9075).', 'derived', 'original', NULL, 'Aus dem vollständig ausgearbeiteten Abschnitt 3.3.43-P5 übernommen.', 'Teilstand 3.3.43-P5.', 'verified', 166),
(10439, '3.9085', 104, 'Bisherige Theorie', '\\mathfrak T_F^{0}=\\operatorname{Cn}\\left(\\mathfrak A_F^{0}\\right)', '\\mathfrak T_F^{0}=\\operatorname{Cn}\\left(\\mathfrak A_F^{0}\\right)\\qquad\\text{(3.9085)}', 'Deduktiver Abschluss der bisherigen Axiomatik.', 'derived', 'original', NULL, 'Aus der bisherigen Primäraxiomatik.', 'Operator Cn als deduktiver Abschluss verwendet.', 'verified', 167),
(10440, '3.9086', 104, 'Erweiterte Theorie', '\\mathfrak T_F^{1}=\\operatorname{Cn}\\left(\\mathfrak A_F^{0}\\cup\\left\\{A_C^{(D)}\\right\\}\\right)', '\\mathfrak T_F^{1}=\\operatorname{Cn}\\left(\\mathfrak A_F^{0}\\cup\\left\\{A_C^{(D)}\\right\\}\\right)\\qquad\\text{(3.9086)}', 'Deduktiver Abschluss nach Aufnahme von Kandidat D.', 'derived', 'original', NULL, 'Aus der erweiterten Primäraxiomatik.', 'Kandidat D ist definiert.', 'verified', 167),
(10441, '3.9094', 104, 'Relative axiomatische Konservativität', '\\operatorname{Cn}\\left(\\mathfrak A^{1}\\right)\\cap\\mathfrak L_0=\\operatorname{Cn}\\left(\\mathfrak A^{0}\\right)\\cap\\mathfrak L_0', '\\operatorname{Cn}\\left(\\mathfrak A^{1}\\right)\\cap\\mathfrak L_0=\\operatorname{Cn}\\left(\\mathfrak A^{0}\\right)\\cap\\mathfrak L_0\\qquad\\text{(3.9094)}', 'Kernformel von Definition 3.3.66.', 'definition', 'original', NULL, 'Definition 3.3.66.', 'Teilsprache L0 definiert.', 'verified', 167),
(10442, '3.9138', 104, 'Ergebnis der relativen Konservativitätsprüfung', 'K_{\\mathrm{cons}}\\left(A_C^{(D)}\\mid\\mathfrak L_{\\neg C}\\right)=1', 'K_{\\mathrm{cons}}\\left(A_C^{(D)}\\mid\\mathfrak L_{\\neg C}\\right)=1\\qquad\\text{(3.9138)}', 'Kandidat D ist bezüglich nichtkohärenzspezifischer Grundstrukturen relativ konservativ.', '', 'original', NULL, 'Aus den Einzelprüfungen zu Raum, Zeit, Kausalität, Dynamik, Symmetrie, Stabilität und Erhaltung.', 'Qualitative Prüfaussage.', 'verified', 167),
(10443, '3.9141', 104, 'Axiomatische Zielgenauigkeit', 'Z_A(A)=1\\Longleftrightarrow\\Delta\\mathfrak T_A\\subseteq\\mathfrak L_A^{\\mathrm{target}}', 'Z_A(A)=1\\Longleftrightarrow\\Delta\\mathfrak T_A\\subseteq\\mathfrak L_A^{\\mathrm{target}}\\qquad\\text{(3.9141)}', 'Kernformel von Definition 3.3.67.', 'definition', 'original', NULL, 'Definition 3.3.67.', 'Zielbereich der neuen Konsequenzen definiert.', 'verified', 167),
(10444, '3.9150', 104, 'Negation von Kandidat D', '\\neg A_C^{(D)}:\\forall z\\in\\Omega_F\\;\\forall\\mathcal S\\subseteq\\mathcal S_F:R_F(\\mathcal S)=1\\Rightarrow C_F(\\mathcal S;z)=0', '\\neg A_C^{(D)}:\\forall z\\in\\Omega_F\\;\\forall\\mathcal S\\subseteq\\mathcal S_F:R_F(\\mathcal S)=1\\Rightarrow C_F(\\mathcal S;z)=0\\qquad\\text{(3.9150)}', 'Explizite Negation des Kandidaten D.', 'derived', 'original', NULL, 'Logische Negation der existenziellen Kandidatenform.', 'Klassische Quantorenlogik.', 'verified', 167),
(10445, '3.9196', 104, 'Minimalitätsstatus von Kandidat D', 'M_A\\left(A_C^{(D)}\\right)=1', 'M_A\\left(A_C^{(D)}\\right)=1\\qquad\\text{(3.9196)}', 'Kandidat D erfüllt die Minimalitätsanforderung.', '', 'original', NULL, 'Aus der Irreduzibilitätsprüfung der Existenz-, Teilstruktur-, Relevanz- und Kohärenzkomponenten.', 'Qualitative Prüfaussage.', 'verified', 167),
(10446, '3.9214', 104, 'Revisionsoffenes Primäraxiom', 'A_{\\mathrm{prim}}=A_{\\mathrm{prim}}^{(v)}', 'A_{\\mathrm{prim}}=A_{\\mathrm{prim}}^{(v)}\\qquad\\text{(3.9214)}', 'Kernformel von Definition 3.3.68.', 'definition', 'original', NULL, 'Definition 3.3.68.', 'Revisionsstand v dokumentiert.', 'verified', 167),
(10447, '3.9218', 104, 'Bewertungsresultat Kandidat D', '\\mathbf P_D=(1,1,1,1,1,1,1,1)', '\\mathbf P_D=(1,1,1,1,1,1,1,1)\\qquad\\text{(3.9218)}', 'Gesamtergebnis der qualitativen Prüfung von Kandidat D.', '', 'original', NULL, 'Aus den Einzelprüfungen N_A, I_A, M_A, D_A, K_A, E_A, Z_A und Z_C.', 'Einsen sind qualitative Erfüllungsindikatoren.', 'verified', 167),
(10448, '3.9229', 104, 'Zulässigkeit von Kandidat D als Primäraxiom', '\\boxed{A_C^{(D)}\\text{ ist als Primäraxiom zulässig.}}', '\\boxed{A_C^{(D)}\\text{ ist als Primäraxiom zulässig.}}\\qquad\\text{(3.9229)}', 'Ergebnis von Satz 3.3.31.', 'theorem', 'original', NULL, 'Aus Nichtableitbarkeit, Unabhängigkeit, Konsistenz, Minimalität, Zielgenauigkeit und Zirkularitätsfreiheit.', 'Prüfbedingungen von Satz 3.3.31 erfüllt.', 'verified', 167),
(10449, '3.9233', 104, 'Primäraxiom der funktionalen Kohärenz', '\\boxed{A_C:\\exists z\\in\\Omega_F\\;\\exists\\mathcal S_C\\subseteq\\mathcal S_F:R_F(\\mathcal S_C)=1\\land C_F(\\mathcal S_C;z)>0.}', '\\boxed{A_C:\\exists z\\in\\Omega_F\\;\\exists\\mathcal S_C\\subseteq\\mathcal S_F:R_F(\\mathcal S_C)=1\\land C_F(\\mathcal S_C;z)>0.}\\qquad\\text{(3.9233)}', 'Endgültiges Primäraxiom der funktionalen Kohärenz.', 'axiom', 'original', NULL, 'Aus dem geprüften Kandidaten D nach Satz 3.3.31.', 'Originäre FRZK-Eigenleistung; kein etabliertes Naturgesetz.', 'verified', 167),
(10450, '3.9264', 104, 'Endgültiger formaler Status des Kohärenzaxioms', '\\boxed{A_C\\in\\mathfrak A_{F,\\mathrm{prim}}.}', '\\boxed{A_C\\in\\mathfrak A_{F,\\mathrm{prim}}.}\\qquad\\text{(3.9264)}', 'A_C ist Primäraxiom des aktuellen FRZK-Theoriestands.', '', 'original', NULL, 'Aus der vollständigen Axiomprüfung.', 'Revisionsoffener Status.', 'verified', 167),
(10451, '3.9271', 104, 'Vierfache Abgrenzung des Primäraxioms', '\\boxed{A_C\\in\\mathfrak A_C,\\qquad A_C\\notin\\mathfrak D_C,\\qquad A_C\\notin\\mathfrak M_C,\\qquad A_C\\notin\\mathfrak O_C.}', '\\boxed{A_C\\in\\mathfrak A_C,\\qquad A_C\\notin\\mathfrak D_C,\\qquad A_C\\notin\\mathfrak M_C,\\qquad A_C\\notin\\mathfrak O_C.}\\qquad\\text{(3.9271)}', 'Trennung von Primäraxiom, Definition, Modellstruktur und Operationalisierung.', '', 'original', NULL, 'Aus der Statusanalyse.', 'Vier wissenschaftliche Rollen getrennt.', 'verified', 167),
(10452, '3.9329', 104, 'Abschluss der Primäraxiomentscheidung', '\\boxed{A_C=\\exists z\\in\\Omega_F\\;\\exists\\mathcal S_C\\subseteq\\mathcal S_F:R_F(\\mathcal S_C)=1\\land C_F(\\mathcal S_C;z)>0}', '\\boxed{A_C=\\exists z\\in\\Omega_F\\;\\exists\\mathcal S_C\\subseteq\\mathcal S_F:R_F(\\mathcal S_C)=1\\land C_F(\\mathcal S_C;z)>0}\\qquad\\text{(3.9329)}', 'Minimales Primäraxiom der funktionalen Kohärenz.', 'axiom', 'original', NULL, 'Endgültige Minimalform nach vollständiger Prüfung.', 'Aktueller FRZK-Theoriestand.', 'verified', 167),
(10453, '3.9330', 104, 'Ergebnis der Axiomprüfung', '\\boxed{N_A=I_A=M_A=D_A=K_A=E_A=Z_A=Z_C=1.}', '\\boxed{N_A=I_A=M_A=D_A=K_A=E_A=Z_A=Z_C=1.}\\qquad\\text{(3.9330)}', 'Gesamtergebnis der Axiomprüfung.', '', 'original', NULL, 'Zusammenfassung aller qualitativen Prüfbedingungen.', 'Einsen sind qualitative Erfüllungsindikatoren.', 'verified', 167),
(10454, '3.9331', 104, 'Endgültige Kohärenzarchitektur', '\\boxed{\\mathfrak C_{3.3.43}=\\left(A_C,\\mathfrak D_C,\\mathfrak M_C,\\mathfrak O_C\\right).}', '\\boxed{\\mathfrak C_{3.3.43}=\\left(A_C,\\mathfrak D_C,\\mathfrak M_C,\\mathfrak O_C\\right).}\\qquad\\text{(3.9331)}', 'Endgültige Klassifikation der Kohärenzarchitektur.', '', 'original', NULL, 'Aus der Schichten- und Statusanalyse.', 'A_C ist einziges bestätigtes Primäraxiom dieses Kohärenzblocks.', 'verified', 167),
(10455, '3.9332', 104, 'Statusklassen der Kohärenzstrukturen', '\\text{Definition}\\;|\\;\\text{abgeleitet}\\;|\\;\\text{Modellannahme}\\;|\\;\\text{Operationalisierung}\\;|\\;\\text{Primäraxiom}', '\\text{Definition}\\;|\\;\\text{abgeleitet}\\;|\\;\\text{Modellannahme}\\;|\\;\\text{Operationalisierung}\\;|\\;\\text{Primäraxiom}\\qquad\\text{(3.9332)}', 'Statusklassen für die anschließende vollständige Statusmatrix.', '', 'original', NULL, 'Aus der wissenschaftlichen Rollenunterscheidung.', 'Statusmatrix folgt ab 3.3.43.585.', 'verified', 167),
(10456, '3.9087', 104, 'Gleichung 3.9087 – Abschnitt 3.3.43-P6', '\\text{Siehe vollständige Formel im Abschnitt 3.3.43, Gleichung (3.9087)}', '\\text{Siehe vollständige Formel im Abschnitt 3.3.43, Gleichung (3.9087)}\\qquad\\text{(3.9087)}', 'Repository-Registrierung der im Abschnittstext vollständig definierten Gleichung (3.9087).', 'derived', 'original', NULL, 'Aus dem vollständig ausgearbeiteten Abschnitt 3.3.43.393 bis 3.3.43.584 übernommen.', 'Teilstand 3.3.43-P6.', 'verified', 167),
