(10715, '3.9338', 104, 'Status der funktionalen Kopplung', '\\operatorname{Stat}_C(\\kappa)=\\begin{cases}\\mathrm{Def},&\\text{für den abstrakten Kopplungsbegriff},\\\\\\mathrm{Mod},&\\text{für eine konkret spezifizierte Kopplungsfunktion}.\\end{cases}', '\\operatorname{Stat}_C(\\kappa)=\\begin{cases}\\mathrm{Def},&\\text{für den abstrakten Kopplungsbegriff},\\\\\\mathrm{Mod},&\\text{für eine konkret spezifizierte Kopplungsfunktion}.\\end{cases}\\qquad\\text{(3.9338)}', 'Trennung zwischen abstraktem Kopplungsbegriff und konkreter modellabhängiger Kopplungsfunktion.', '', 'original', NULL, 'Aus der Rollenunterscheidung von Definition und Modellannahme.', 'Kopplungsbegriff vorhanden.', 'verified', 168),
(10716, '3.9340', 104, 'Definition positiver lokaler funktionaler Kohärenz', 'C_F(X_i,X_j;z)>0\\Longleftrightarrow\\left[\\mathcal C(X_i,X_j;z)=1\\land K_F(X_i,X_j;z)=1\\land\\kappa_{ij}(z)>0\\right]', 'C_F(X_i,X_j;z)>0\\Longleftrightarrow\\left[\\mathcal C(X_i,X_j;z)=1\\land K_F(X_i,X_j;z)=1\\land\\kappa_{ij}(z)>0\\right]\\qquad\\text{(3.9340)}', 'Kernbedingung der lokalen funktionalen Kohärenz.', 'definition', 'original', NULL, 'Aus Definition 3.3.53.', 'Vergleichbarkeit, Konsistenz und Kopplung definiert.', 'verified', 168),
(10717, '3.9341', 104, 'Status der Kohärenz eines Teilverbandes', '\\operatorname{Stat}_C\\left(C_F(\\mathcal S_C;z)\\right)=\\mathrm{Abl}', '\\operatorname{Stat}_C\\left(C_F(\\mathcal S_C;z)\\right)=\\mathrm{Abl}\\qquad\\text{(3.9341)}', 'Kohärenz eines Teilverbandes ist eine abgeleitete Konstruktion.', '', 'original', NULL, 'Aus lokalen Kohärenzrelationen und Aggregation.', 'Lokale Kohärenz definiert.', 'verified', 168),
(10718, '3.9342', 104, 'Status der Aggregationsfunktion', '\\operatorname{Stat}_C(\\mathcal A_C)=\\mathrm{Mod}', '\\operatorname{Stat}_C(\\mathcal A_C)=\\mathrm{Mod}\\qquad\\text{(3.9342)}', 'Eine konkrete Aggregationsfunktion ist eine Modellannahme.', '', 'original', NULL, 'Aus der Nichtfestlegung durch das Primäraxiom.', 'Aggregation ist zur Bildung größerer Kohärenzverbände optional spezifizierbar.', 'verified', 168),
