INSERT INTO `equation_dependencies` (`dependency_id`, `equation_id`, `depends_on_equation_id`, `dependency_type`, `dependency_note`) VALUES
(1, 4218, 4217, 'uses', 'Definition 3.3.1 verwendet das in Primäraxiom I eingeführte Wirksamkeitsprädikat.'),
(2, 4219, 4217, 'derived_from', 'Primäraxiom I garantiert die Existenz mindestens eines Elements mit omega gleich 1.'),
(3, 4219, 4218, 'uses', 'Die Nichtleere bezieht sich auf die in Gleichung (3.4002) definierte Menge.'),
(4, 4220, 4218, 'derived_from', 'Das Zugehörigkeitskriterium ist die äquivalente Elementform der Mengendefinition.'),
(5, 4221, 4217, 'uses', 'Der Definitions- und Wertebereich präzisiert das in Primäraxiom I verwendete Prädikat omega.'),
(6, 4222, 4219, 'derived_from', 'Die Wahl eines Elements ist aufgrund der Nichtleere von S_el möglich.'),
(7, 4223, 4218, 'uses', 'Das kartesische Produkt wird aus der in Gleichung (3.4002) definierten Menge gebildet.'),
(8, 4224, 4223, 'uses', 'Gleichung (3.4008) wiederholt den bereits in Gleichung (3.4007) vorbereiteten kartesischen Relationsbereich.'),
(9, 4225, 4224, 'uses', 'Die Relation R wird als Teilmenge des in Gleichung (3.4008) angegebenen kartesischen Produkts definiert.'),
(10, 4226, 4224, 'uses', 'Der Definitionsbereich von rho ist die Potenzmenge des Relationsbereichs aus Gleichung (3.4008).'),
(11, 4227, 4225, 'uses', 'Primäraxiom II quantifiziert über Relationen gemäß Gleichung (3.4009).'),
(12, 4227, 4226, 'uses', 'Primäraxiom II verwendet das in Gleichung (3.4010) definierte Prädikat rho.'),
(13, 4228, 4225, 'special_case_of', 'Gleichung (3.4012) beschreibt den Spezialfall einer Relation zwischen verschiedenen Zuständen.'),
(14, 4229, 4227, 'uses', 'Die Menge R_f verwendet die durch Primäraxiom II gesicherte funktionale Relationswirksamkeit.'),
(15, 4230, 4227, 'derived_from', 'Die Nichtleere folgt aus der axiomatischen Existenz mindestens einer funktional wirksamen Relation.'),
(16, 4230, 4229, 'uses', 'Die Nichtleere bezieht sich auf die in Gleichung (3.4013) definierte Menge R_f.'),
(17, 4231, 4229, 'derived_from', 'Gleichung (3.4015) ist die Zugehörigkeitsform der in Gleichung (3.4013) definierten Menge R_f.'),
(18, 4231, 4227, 'uses', 'Die Existenz funktional wirksamer Relationen ist durch Primäraxiom II gesichert.'),
(19, 4232, 4231, 'uses', 'Gleichung (3.4016) wendet Definition 3.3.2 auf ein konkretes Zustandspaar an.'),
(20, 4233, 4232, 'special_case_of', 'Selbstrelation als Spezialfall eines Zustandspaars innerhalb R.'),
(21, 4234, 4232, 'special_case_of', 'Fremdrelation als Spezialfall mit Verschiedenheitsbedingung.'),
(22, 4236, 4235, 'uses', 'Die Symmetriebedingung vergleicht ein Paar mit dem umgekehrten Paar.'),
(23, 4237, 4232, 'uses', 'Die ausgehende Relationsumgebung basiert auf Paaren der Form (delta_i,delta_j).'),
(24, 4238, 4232, 'uses', 'Die eingehende Relationsumgebung basiert auf Paaren der Form (delta_j,delta_i).'),
(25, 4239, 4237, 'uses', 'Isolation setzt die Leere der ausgehenden Relationsumgebung voraus.'),
(26, 4239, 4238, 'uses', 'Isolation setzt die Leere der eingehenden Relationsumgebung voraus.'),
(27, 4240, 4237, 'derived_from', 'Der ausgehende Relationsgrad ist die Mächtigkeit der ausgehenden Relationsumgebung.'),
(28, 4241, 4238, 'derived_from', 'Der eingehende Relationsgrad ist die Mächtigkeit der eingehenden Relationsumgebung.'),
(29, 4242, 4231, 'uses', 'Die Relationsstruktur verwendet den durch Definition 3.3.2 bestimmten Relationsbegriff.'),
(30, 4245, 4244, 'uses', 'Gleichung (3.4029) wendet die in Gleichung (3.4028) definierte Abbildung T an.'),
(31, 4246, 4244, 'uses', 'Der Definitionsbereich von tau ist die Menge aller Abbildungen gemäß Gleichung (3.4028).'),
(32, 4247, 4244, 'uses', 'Primäraxiom III quantifiziert über Abbildungen auf S_el.'),
(33, 4247, 4246, 'uses', 'Primäraxiom III verwendet das in Gleichung (3.4030) definierte Prädikat tau.'),
(34, 4248, 4244, 'special_case_of', 'Die Identitätsabbildung ist ein Spezialfall einer Abbildung auf S_el.'),
(35, 4249, 4245, 'special_case_of', 'Die zustandsändernde Transformation ist ein Spezialfall mit Verschiedenheitsbedingung.'),
(36, 4250, 4247, 'uses', 'Die Menge T_f verwendet die durch Primäraxiom III gesicherte funktionale Transformationswirksamkeit.'),
(37, 4251, 4247, 'derived_from', 'Die Nichtleere folgt aus der axiomatischen Existenz mindestens einer funktional wirksamen Transformation.'),
(38, 4251, 4250, 'uses', 'Die Nichtleere bezieht sich auf die in Gleichung (3.4034) definierte Menge T_f.'),
(39, 4252, 4244, 'uses', 'Die Komposition verwendet zwei Abbildungen auf dem elementaren funktionalen Zustandsbereich.'),
(40, 4253, 4245, 'derived_from', 'Der Graph der Transformation wird aus den Zustand-Bild-Paaren der Abbildung gebildet.'),
(41, 4253, 4231, 'uses', 'Der Graph einer Transformation ist eine spezielle Relation auf S_el.'),
(42, 4254, 4250, 'derived_from', 'Gleichung (3.4038) ist die Zugehörigkeitsform der in Gleichung (3.4034) definierten Menge T_f.'),
(43, 4254, 4247, 'uses', 'Die Existenz funktional wirksamer Transformationen ist durch Primäraxiom III gesichert.'),
(44, 4255, 4254, 'uses', 'Gleichung (3.4039) wendet Definition 3.3.3 auf einen Zustand an.'),
(45, 4256, 4255, 'special_case_of', 'Zustandserhaltung als Spezialfall der Anwendung einer funktionalen Transformation.'),
(46, 4257, 4256, 'derived_from', 'Die Fixpunktmenge fasst alle Zustände zusammen, die Gleichung (3.4040) erfüllen.'),
