INSERT INTO `object_dependencies` (`object_dependency_id`, `object_type_from`, `object_id_from`, `object_type_to`, `object_id_to`, `dependency_type`, `note`) VALUES
(1, 'definition', 960, 'axiom', 1, 'derives_from', 'Definition 3.3.1 präzisiert den durch Primäraxiom I eröffneten funktionalen Gegenstandsbereich.'),
(2, 'axiom', 2, 'definition', 960, 'depends_on', 'Primäraxiom II verwendet den in Definition 3.3.1 eingeführten elementaren funktionalen Zustandsbereich.'),
(3, 'definition', 961, 'axiom', 2, 'derives_from', 'Definition 3.3.2 präzisiert den durch Primäraxiom II eröffneten Relationsbereich.'),
(4, 'definition', 961, 'definition', 960, 'depends_on', 'Definition 3.3.2 verwendet den in Definition 3.3.1 festgelegten elementaren funktionalen Zustandsbereich.'),
(5, 'axiom', 3, 'definition', 960, 'depends_on', 'Primäraxiom III verwendet den in Definition 3.3.1 eingeführten elementaren funktionalen Zustandsbereich.'),
